pub fn emit_wasm_module_native(
    program: &Validated<LoweredProgram>,
) -> Result<WasmModule, Diagnostic> {
    NativeLoweredEmitter::new(program.as_ref()).emit()
}

pub fn emit_wasm_module_native_with_abi(
    program: &Validated<LoweredProgram>,
    abi_metadata: &AbiMetadata,
) -> Result<WasmModule, Diagnostic> {
    emit_wasm_module_native(program).map(|module| add_abi_custom_section(module, abi_metadata))
}

pub fn emit_wasm_binary_native(program: &Validated<LoweredProgram>) -> Result<Vec<u8>, Diagnostic> {
    let module = emit_wasm_module_native(program)?;
    validate_native_final_module(&module)?;
    module.to_wasm_encoder()
}

pub fn emit_wasm_binary_native_with_abi(
    program: &Validated<LoweredProgram>,
    abi_metadata: &AbiMetadata,
) -> Result<Vec<u8>, Diagnostic> {
    let module = emit_wasm_module_native_with_abi(program, abi_metadata)?;
    validate_native_final_module(&module)?;
    module.to_wasm_encoder()
}

fn add_abi_custom_section(module: WasmModule, abi_metadata: &AbiMetadata) -> WasmModule {
    module.custom_section(WasmCustomSection::new(
        ABI_CUSTOM_SECTION_NAME,
        abi_metadata.to_custom_section_payload(),
    ))
}

pub(crate) fn validate_no_pseudo_intrinsics(module: &WasmModule) -> Result<(), Diagnostic> {
    for import in &module.imports {
        reject_pseudo_symbol("import", &import.func_symbol)?;
    }
    for function in &module.functions {
        reject_pseudo_symbol("function", &function.symbol)?;
        for instr in &function.body {
            if let WasmInstr::Call(symbol) = instr {
                reject_pseudo_symbol("call", symbol)?;
            }
        }
    }
    for export in &module.exports {
        if let WasmExportKind::Func(symbol) = &export.kind {
            reject_pseudo_symbol("export", symbol)?;
        }
    }
    Ok(())
}

pub(crate) fn validate_native_final_module(module: &WasmModule) -> Result<(), Diagnostic> {
    validate_no_pseudo_intrinsics(module)?;
    validate_no_unlinked_default_host_imports(module)?;
    validate_global_references_declared(module)
}

fn validate_no_unlinked_default_host_imports(module: &WasmModule) -> Result<(), Diagnostic> {
    for import in &module.imports {
        if import.module == "host"
            && matches!(
                import.name.as_str(),
                "function.callMethod" | "reflectApply" | "reflectConstruct"
            )
        {
            return Err(unsupported(&format!(
                "native LoweredProgram emitter does not support unlinked host import {}.{}",
                import.module, import.name
            )));
        }
    }
    Ok(())
}

fn validate_global_references_declared(module: &WasmModule) -> Result<(), Diagnostic> {
    let declared_globals = module
        .globals
        .iter()
        .map(|global| global.symbol.as_str())
        .collect::<HashSet<_>>();

    for function in &module.functions {
        for instr in &function.body {
            let symbol = match instr {
                WasmInstr::GlobalGet(symbol) | WasmInstr::GlobalSet(symbol) => symbol,
                _ => continue,
            };
            if !declared_globals.contains(symbol.as_str()) {
                return Err(Diagnostic::invariant(format!(
                    "unresolved global symbol {symbol} reached final native wasm module from {}",
                    function.symbol
                ))
                .with_phase("native-emitter"));
            }
        }
    }

    Ok(())
}

fn reject_pseudo_symbol(location: &'static str, symbol: &str) -> Result<(), Diagnostic> {
    if symbol.starts_with("$pseudo_") {
        return Err(Diagnostic::invariant(format!(
            "pseudo-intrinsic {symbol} reached final native wasm module as {location}"
        ))
        .with_phase("native-emitter"));
    }
    Ok(())
}

fn append_host_import_once(
    module: WasmModule,
    imported_symbols: &mut HashSet<String>,
    import: HostImport,
) -> WasmModule {
    let spec = import.spec();
    if imported_symbols.insert(spec.wat_symbol.to_owned()) {
        module.import(wasm_import_from_host_spec(&spec))
    } else {
        module
    }
}

fn append_called_host_imports(
    mut module: WasmModule,
    imported_symbols: &mut HashSet<String>,
    required_imports: impl IntoIterator<Item = HostImport>,
    functions: &[WasmFunction],
) -> WasmModule {
    let called_symbols = functions
        .iter()
        .flat_map(|function| &function.body)
        .filter_map(|instr| match instr {
            WasmInstr::Call(symbol) => Some(symbol.as_str()),
            _ => None,
        })
        .collect::<HashSet<_>>();

    for import in required_imports {
        let spec = import.spec();
        if called_symbols.contains(spec.wat_symbol) {
            module = append_host_import_once(module, imported_symbols, import);
        }
    }
    module
}

fn functions_call_symbol(functions: &[WasmFunction], symbol: &str) -> bool {
    functions.iter().any(|function| {
        function
            .body
            .iter()
            .any(|instr| matches!(instr, WasmInstr::Call(call) if call == symbol))
    })
}

fn prune_unreachable_native_runtime_functions(
    functions: Vec<WasmFunction>,
    native_runtime_symbols: &HashSet<String>,
) -> Vec<WasmFunction> {
    let calls_by_symbol = functions
        .iter()
        .map(|function| {
            (
                function.symbol.clone(),
                function
                    .body
                    .iter()
                    .filter_map(|instr| match instr {
                        WasmInstr::Call(symbol) => Some(symbol.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut reachable = HashSet::new();
    let mut stack = functions
        .iter()
        .filter(|function| !native_runtime_symbols.contains(&function.symbol))
        .map(|function| function.symbol.clone())
        .collect::<Vec<_>>();

    while let Some(symbol) = stack.pop() {
        if !reachable.insert(symbol.clone()) {
            continue;
        }
        if let Some(calls) = calls_by_symbol.get(&symbol) {
            stack.extend(calls.iter().cloned());
        }
    }

    functions
        .into_iter()
        .filter(|function| {
            !native_runtime_symbols.contains(&function.symbol)
                || reachable.contains(&function.symbol)
        })
        .collect()
}

fn prune_unreachable_functions_from_start(functions: Vec<WasmFunction>) -> Vec<WasmFunction> {
    let calls_by_symbol = functions
        .iter()
        .map(|function| {
            (
                function.symbol.clone(),
                function
                    .body
                    .iter()
                    .filter_map(|instr| match instr {
                        WasmInstr::Call(symbol) => Some(symbol.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut reachable = HashSet::new();
    let mut stack = vec![START_SYMBOL.to_owned()];

    while let Some(symbol) = stack.pop() {
        if !reachable.insert(symbol.clone()) {
            continue;
        }
        if let Some(calls) = calls_by_symbol.get(&symbol) {
            stack.extend(calls.iter().cloned());
        }
    }

    functions
        .into_iter()
        .filter(|function| reachable.contains(&function.symbol))
        .collect()
}

