#[derive(Clone, PartialEq, Eq)]
struct StaticSymbolValue {
    identity: LocalId,
    description: Option<String>,
}

impl StaticSymbolValue {
    fn unique(identity: LocalId) -> Self {
        Self {
            identity,
            description: None,
        }
    }

    fn well_known(index: u32, description: String) -> Self {
        Self {
            identity: static_well_known_symbol_identity(index),
            description: Some(description),
        }
    }

    fn console_bytes(&self) -> Option<Vec<u8>> {
        self.description
            .as_ref()
            .map(|description| format!("Symbol({description})").into_bytes())
    }
}

