#[derive(Clone)]
struct StaticObjectValue {
    props: HashMap<String, LoweredExpr>,
    attrs: HashMap<String, StaticPropertyAttrs>,
    key_order: Vec<String>,
    prototype: Option<StaticPrototype>,
    extensible: bool,
    builtin_error: Option<BuiltinErrorConstructor>,
    private_brands: HashSet<u32>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct StaticPropertyAttrs {
    writable: bool,
    enumerable: bool,
    configurable: bool,
}

impl StaticPropertyAttrs {
    fn object_literal() -> Self {
        Self {
            writable: true,
            enumerable: true,
            configurable: true,
        }
    }

    fn define_property_default() -> Self {
        Self {
            writable: false,
            enumerable: false,
            configurable: false,
        }
    }

    fn private_field() -> Self {
        Self {
            writable: true,
            enumerable: false,
            configurable: false,
        }
    }
}

fn static_canonical_property_index_key(key: &str) -> Option<u32> {
    let index = key.parse::<u32>().ok()?;
    (index != u32::MAX && key == index.to_string()).then_some(index)
}

fn static_order_own_property_keys<I>(keys: I) -> Vec<String>
where
    I: IntoIterator<Item = String>,
{
    let mut indexed = Vec::new();
    let mut named = Vec::new();
    for key in keys {
        if let Some(index) = static_canonical_property_index_key(&key) {
            indexed.push((index, key));
        } else {
            named.push(key);
        }
    }
    indexed.sort_by_key(|(index, _)| *index);
    indexed
        .into_iter()
        .map(|(_, key)| key)
        .chain(named)
        .collect()
}

fn static_well_known_symbol_identity(index: u32) -> LocalId {
    LocalId(STATIC_WELL_KNOWN_SYMBOL_ROOT_OFFSET + index as usize)
}

impl StaticObjectValue {
    fn from_props(props: &[(String, LoweredExpr)]) -> Self {
        let mut value = Self {
            props: HashMap::new(),
            attrs: HashMap::new(),
            key_order: Vec::new(),
            prototype: None,
            extensible: true,
            builtin_error: None,
            private_brands: HashSet::new(),
        };
        for (key, expr) in props {
            value.set(key.clone(), expr.clone());
        }
        value
    }

    fn from_props_with_non_enumerable(
        props: &[(String, LoweredExpr)],
        non_enumerable: u32,
    ) -> Self {
        let mut value = Self {
            props: HashMap::new(),
            attrs: HashMap::new(),
            key_order: Vec::new(),
            prototype: None,
            extensible: true,
            builtin_error: None,
            private_brands: HashSet::new(),
        };
        for (index, (key, expr)) in props.iter().enumerate() {
            let mut attrs = StaticPropertyAttrs::object_literal();
            attrs.enumerable =
                index >= u32::BITS as usize || (non_enumerable & (1u32 << index)) == 0;
            value.define(key.clone(), expr.clone(), attrs);
        }
        value
    }

    fn get(&self, key: &str) -> Option<&LoweredExpr> {
        self.props.get(key)
    }

    fn descriptor(&self, key: &str) -> Option<(&LoweredExpr, StaticPropertyAttrs)> {
        let value = self.props.get(key)?;
        let attrs = self
            .attrs
            .get(key)
            .copied()
            .unwrap_or_else(StaticPropertyAttrs::object_literal);
        Some((value, attrs))
    }

    fn set(&mut self, key: String, value: LoweredExpr) {
        if let Some(attrs) = self.attrs.get(&key).copied() {
            if !attrs.writable {
                return;
            }
        } else if !self.extensible {
            return;
        }
        let attrs = self
            .attrs
            .get(&key)
            .copied()
            .unwrap_or_else(StaticPropertyAttrs::object_literal);
        self.define(key, value, attrs);
    }

    fn define(&mut self, key: String, value: LoweredExpr, attrs: StaticPropertyAttrs) {
        if !self.props.contains_key(&key) && !self.extensible {
            return;
        }
        if !self.props.contains_key(&key) {
            self.key_order.push(key.clone());
        }
        self.props.insert(key.clone(), value);
        self.attrs.insert(key, attrs);
    }

    fn delete(&mut self, key: &str) -> bool {
        let Some(attrs) = self.attrs.get(key).copied() else {
            return true;
        };
        if !attrs.configurable {
            return false;
        }
        self.props.remove(key);
        self.attrs.remove(key);
        self.key_order.retain(|existing| existing != key);
        true
    }

    fn set_prototype(&mut self, prototype: LocalId) {
        self.prototype = Some(StaticPrototype::Object(prototype));
    }

    fn set_null_prototype(&mut self) {
        self.prototype = Some(StaticPrototype::Null);
    }

    fn add_private_brand(&mut self, brand: u32) {
        self.private_brands.insert(brand);
    }

    fn has_private_brand(&self, brand: u32) -> bool {
        self.private_brands.contains(&brand)
    }

    fn prevent_extensions(&mut self) {
        self.extensible = false;
    }

    fn seal(&mut self) {
        self.extensible = false;
        for attrs in self.attrs.values_mut() {
            attrs.configurable = false;
        }
    }

    fn freeze(&mut self) {
        self.extensible = false;
        for attrs in self.attrs.values_mut() {
            attrs.configurable = false;
            attrs.writable = false;
        }
    }

    fn is_sealed(&self) -> bool {
        !self.extensible && self.attrs.values().all(|attrs| !attrs.configurable)
    }

    fn is_frozen(&self) -> bool {
        self.is_sealed()
            && self
                .attrs
                .values()
                .all(|attrs| !attrs.writable && !attrs.configurable)
    }

    fn keys(&self) -> Vec<String> {
        static_order_own_property_keys(
            self.key_order
                .iter()
                .filter(|key| {
                    if static_symbol_property_local(key).is_some() {
                        return false;
                    }
                    self.attrs
                        .get(*key)
                        .copied()
                        .unwrap_or_else(StaticPropertyAttrs::object_literal)
                        .enumerable
                })
                .cloned()
                .collect::<Vec<_>>(),
        )
    }

    fn own_property_names(&self) -> Vec<String> {
        static_order_own_property_keys(
            self.key_order
                .iter()
                .filter(|key| static_symbol_property_local(key).is_none())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

