fn static_object_from_entries_from_expr_with_functions(
    expr: &LoweredExpr,
    locals: &HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<StaticObjectValue> {
    let entries = static_array_from_expr_with_functions(expr, locals, functions)?;
    let mut object = StaticObjectValue::from_props(&[]);
    for entry in entries {
        let pair = static_array_from_expr_with_functions(&entry, locals, functions)?;
        if pair.len() < 2 {
            return None;
        }
        let key = static_property_key_from_locals_with_functions(locals, &pair[0], functions)?;
        let value = static_value_from_expr_with_functions(&pair[1], locals, functions)
            .and_then(static_value_to_expr)?;
        object.set(key, value);
    }
    Some(object)
}

fn apply_static_object_assign_from_args(
    args: &[LoweredExpr],
    locals: &mut HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<LocalId> {
    if args.len() != 2 {
        return None;
    }
    let LoweredExpr::Local(target, _) = &args[0] else {
        return None;
    };
    let target = resolve_static_object_root(locals, *target)?;
    let entries =
        static_object_assign_entries_from_expr_with_functions(&args[1], locals, functions)?;
    let Some(StaticValue::Object(target_object)) = locals.get_mut(&target) else {
        return None;
    };
    for (key, value) in entries {
        target_object.set(key, value);
    }
    Some(target)
}

fn static_object_spread_value_from_args(
    args: &[LoweredExpr],
    locals: &HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<StaticValue> {
    if args.len() != 2 {
        return None;
    }
    if let LoweredExpr::Local(target, _) = &args[0] {
        static_object_assign_entries_from_expr_with_functions(&args[1], locals, functions)?;
        return Some(StaticValue::ObjectAlias(resolve_static_object_root(
            locals, *target,
        )?));
    }

    let mut object =
        static_object_value_owned_from_expr_with_functions(&args[0], locals, functions)?;
    let entries =
        static_object_assign_entries_from_expr_with_functions(&args[1], locals, functions)?;
    for (key, value) in entries {
        object.set(key, value);
    }
    Some(StaticValue::Object(object))
}

