fn static_has_own_property_from_locals(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<bool> {
    if let LoweredExpr::BuiltinErrorPrototype(constructor, _) = obj {
        return Some(builtin_error_prototype_has_own_property(*constructor, key));
    }
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Object(object) => Some(object.get(key).is_some()),
        StaticValue::ObjectAlias(local) => Some(
            static_object_value_from_local(locals, local)?
                .get(key)
                .is_some(),
        ),
        StaticValue::Array(elements) => {
            if key == "length" {
                return Some(true);
            }
            let index = key.parse::<usize>().ok()?;
            Some(index < elements.len())
        }
        StaticValue::SparseArray(slots) => {
            if key == "length" {
                return Some(true);
            }
            let index = canonical_static_array_index(key)?;
            Some(slots.get(index).is_some_and(Option::is_some))
        }
        StaticValue::Primitive(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::Symbol(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedNumber
        | StaticValue::TaggedRuntimeValue => None,
    }
}

fn static_property_in_from_locals(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<bool> {
    if static_object_property_from_locals(locals, obj, key).is_some() {
        return Some(true);
    }
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Object(_) | StaticValue::ObjectAlias(_) => Some(false),
        StaticValue::Array(elements) => {
            if key == "length" {
                return Some(true);
            }
            let index = key.parse::<usize>().ok()?;
            Some(index < elements.len())
        }
        StaticValue::SparseArray(slots) => {
            if key == "length" {
                return Some(true);
            }
            let index = canonical_static_array_index(key)?;
            Some(slots.get(index).is_some_and(Option::is_some))
        }
        StaticValue::Primitive(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::Symbol(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedNumber
        | StaticValue::TaggedRuntimeValue => None,
    }
}

fn builtin_error_prototype_has_own_property(
    _constructor: BuiltinErrorConstructor,
    key: &str,
) -> bool {
    matches!(key, "constructor" | "name" | "message")
}

fn static_object_property<'a>(
    ctx: &'a FunctionCtx,
    obj: &'a LoweredExpr,
    key: &str,
) -> Option<&'a LoweredExpr> {
    static_object_property_from_locals(&ctx.static_locals, obj, key)
}

fn static_object_property_from_locals<'a>(
    locals: &'a HashMap<LocalId, StaticValue>,
    obj: &'a LoweredExpr,
    key: &str,
) -> Option<&'a LoweredExpr> {
    static_object_property_descriptor_from_locals(locals, obj, key).map(|(value, _)| value)
}

fn static_object_property_descriptor_from_locals<'a>(
    locals: &'a HashMap<LocalId, StaticValue>,
    obj: &'a LoweredExpr,
    key: &str,
) -> Option<(&'a LoweredExpr, StaticPropertyAttrs)> {
    if static_expr_is_global_this(obj)
        && let Some(object) = static_object_value_from_root(locals, STATIC_GLOBAL_THIS_ROOT)
    {
        return static_object_property_descriptor_from_value(
            locals,
            object,
            key,
            &mut HashSet::new(),
        );
    }
    let local = match obj {
        LoweredExpr::Local(local, _) | LoweredExpr::EnvCellGet(local, _) => *local,
        _ => return None,
    };
    let props = static_object_value_from_local(locals, local)?;
    static_object_property_descriptor_from_value(locals, props, key, &mut HashSet::new())
}

fn static_object_property_can_write(
    ctx: &FunctionCtx,
    obj: &LoweredExpr,
    key: &str,
) -> Option<bool> {
    static_object_property_can_write_from_locals(&ctx.static_locals, obj, key)
}

fn static_object_property_can_write_from_locals(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
) -> Option<bool> {
    if static_expr_is_global_this(obj) {
        let object = static_object_value_from_root(locals, STATIC_GLOBAL_THIS_ROOT)?;
        if let Some((_, attrs)) = object.descriptor(key) {
            return Some(attrs.writable);
        }
        return Some(object.extensible);
    }
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let object = static_object_value_from_local(locals, *local)?;
    if let Some((_, attrs)) = object.descriptor(key) {
        return Some(attrs.writable);
    }
    Some(object.extensible)
}

fn static_object_property_delete_result(
    ctx: &FunctionCtx,
    obj: &LoweredExpr,
    key: &str,
) -> Option<bool> {
    static_object_property_delete_result_from_locals(&ctx.static_locals, obj, key)
}

fn static_object_property_delete_result_from_locals(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
) -> Option<bool> {
    if static_expr_is_global_this(obj) {
        let object = static_object_value_from_root(locals, STATIC_GLOBAL_THIS_ROOT)?;
        return Some(
            object
                .descriptor(key)
                .is_none_or(|(_, attrs)| attrs.configurable),
        );
    }
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let object = static_object_value_from_local(locals, *local)?;
    Some(
        object
            .descriptor(key)
            .is_none_or(|(_, attrs)| attrs.configurable),
    )
}

fn static_object_property_descriptor_owned_from_expr(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<(LoweredExpr, StaticPropertyAttrs)> {
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Primitive(LoweredExpr::ArrowFn { func_id, .. }) => {
            let value = static_function_metadata_property_expr(functions, func_id, key)?;
            Some((value, static_function_metadata_property_attrs()))
        }
        StaticValue::Object(object) => object
            .descriptor(key)
            .map(|(value, attrs)| (value.clone(), attrs)),
        StaticValue::ObjectAlias(local) => static_object_value_from_root(locals, local)?
            .descriptor(key)
            .map(|(value, attrs)| (value.clone(), attrs)),
        StaticValue::Array(_)
        | StaticValue::SparseArray(_)
        | StaticValue::Primitive(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::Symbol(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedNumber
        | StaticValue::TaggedRuntimeValue => None,
    }
}

fn static_object_length_property_expr(
    obj: &LoweredExpr,
    span: Span,
    locals: &HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let value = match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Object(object) => object.get("length").cloned(),
        StaticValue::ObjectAlias(local) => static_object_value_from_root(locals, local)?
            .get("length")
            .cloned(),
        StaticValue::Array(_)
        | StaticValue::SparseArray(_)
        | StaticValue::Primitive(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::Symbol(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedNumber
        | StaticValue::TaggedRuntimeValue => return None,
    };
    match value {
        Some(value) => static_value_from_expr_with_functions(&value, locals, functions)
            .and_then(static_value_to_expr)
            .or(Some(value)),
        None => Some(LoweredExpr::Undefined(span)),
    }
}

fn static_get_length_expr_with_functions(
    obj: &LoweredExpr,
    span: Span,
    locals: &HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    if let Some(len) = static_array_len_from_expr_with_functions(obj, locals, functions) {
        return Some(LoweredExpr::Number(len as i32, span));
    }
    if let Some(value) = static_object_length_property_expr(obj, span, locals, functions) {
        return Some(value);
    }
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Primitive(LoweredExpr::String(value, _)) => {
            Some(LoweredExpr::Number(value.chars().count() as i32, span))
        }
        StaticValue::Primitive(
            LoweredExpr::Number(_, _)
            | LoweredExpr::DecimalNumber(_, _)
            | LoweredExpr::BigIntLiteral { .. }
            | LoweredExpr::Bool(_, _),
        )
        | StaticValue::Symbol(_)
        | StaticValue::TaggedNumber => Some(LoweredExpr::Undefined(span)),
        StaticValue::Primitive(_)
        | StaticValue::Object(_)
        | StaticValue::ObjectAlias(_)
        | StaticValue::Array(_)
        | StaticValue::SparseArray(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedRuntimeValue => None,
    }
}

fn resolve_static_object_root(
    locals: &HashMap<LocalId, StaticValue>,
    local: LocalId,
) -> Option<LocalId> {
    let mut current = local;
    let mut visited = HashSet::new();
    loop {
        if !visited.insert(current) {
            return None;
        }
        match locals.get(&current)? {
            StaticValue::Object(_) => return Some(current),
            StaticValue::ObjectAlias(next) => current = *next,
            _ => return None,
        }
    }
}

fn static_object_value_from_local(
    locals: &HashMap<LocalId, StaticValue>,
    local: LocalId,
) -> Option<&StaticObjectValue> {
    let root = resolve_static_object_root(locals, local)?;
    static_object_value_from_root(locals, root)
}

fn static_object_value_from_root(
    locals: &HashMap<LocalId, StaticValue>,
    root: LocalId,
) -> Option<&StaticObjectValue> {
    match locals.get(&root)? {
        StaticValue::Object(object) => Some(object),
        _ => None,
    }
}

fn static_object_property_descriptor_from_value<'a>(
    locals: &'a HashMap<LocalId, StaticValue>,
    object: &'a StaticObjectValue,
    key: &str,
    visited: &mut HashSet<LocalId>,
) -> Option<(&'a LoweredExpr, StaticPropertyAttrs)> {
    if let Some(descriptor) = object.descriptor(key) {
        return Some(descriptor);
    }
    let StaticPrototype::Object(prototype) = object.prototype? else {
        return None;
    };
    if !visited.insert(prototype) {
        return None;
    }
    let prototype = static_object_value_from_local(locals, prototype)?;
    static_object_property_descriptor_from_value(locals, prototype, key, visited)
}

fn static_descriptor_attrs_from_expr(
    locals: &HashMap<LocalId, StaticValue>,
    descriptor: &LoweredExpr,
    functions: &[LoweredFunction],
) -> StaticPropertyAttrs {
    let defaults = StaticPropertyAttrs::define_property_default();
    StaticPropertyAttrs {
        writable: static_bool_property_from_expr(locals, descriptor, "writable", functions)
            .unwrap_or(defaults.writable),
        enumerable: static_bool_property_from_expr(locals, descriptor, "enumerable", functions)
            .unwrap_or(defaults.enumerable),
        configurable: static_bool_property_from_expr(locals, descriptor, "configurable", functions)
            .unwrap_or(defaults.configurable),
    }
}

fn static_object_property_owned_from_expr_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    if let Some(value) = static_object_property_from_locals(locals, obj, key) {
        return Some(value.clone());
    }
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Object(object) => object.get(key).cloned(),
        StaticValue::ObjectAlias(root) => {
            static_object_value_from_root(locals, root).and_then(|object| object.get(key).cloned())
        }
        StaticValue::Primitive(LoweredExpr::ArrowFn { func_id, .. }) => {
            static_function_metadata_property_expr(functions, func_id, key)
        }
        _ => None,
    }
}

fn static_function_metadata_property_expr(
    functions: &[LoweredFunction],
    func_id: FuncId,
    key: &str,
) -> Option<LoweredExpr> {
    let function = functions.iter().find(|function| function.id == func_id)?;
    let span = Span::generated("function-metadata-property");
    match key {
        "name" => Some(LoweredExpr::String(
            function.metadata_name.clone().unwrap_or_default(),
            span,
        )),
        "length" => Some(LoweredExpr::Number(
            function.metadata_length.unwrap_or_else(|| {
                function
                    .params
                    .len()
                    .saturating_sub(usize::from(function.uses_receiver))
            }) as i32,
            span,
        )),
        _ => None,
    }
}

fn static_function_metadata_property_attrs() -> StaticPropertyAttrs {
    StaticPropertyAttrs {
        writable: false,
        enumerable: false,
        configurable: true,
    }
}

fn static_object_dynamic_property_owned_from_expr_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let key = static_property_key_from_locals_with_functions(locals, key, functions)?;
    static_object_property_owned_from_expr_with_functions(locals, obj, &key, functions)
}

fn static_array_property_owned_from_expr_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let index = key.parse::<usize>().ok()?;
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Array(elements) => elements.get(index).cloned(),
        StaticValue::SparseArray(slots) => {
            Some(
                slots.get(index).cloned().flatten().unwrap_or_else(|| {
                    LoweredExpr::Undefined(Span::generated("sparse-array-hole"))
                }),
            )
        }
        _ => None,
    }
}

fn static_string_property_owned_from_expr_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let index = canonical_static_array_index(key)?;
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Primitive(LoweredExpr::String(value, _)) => value
            .chars()
            .nth(index)
            .map(|ch| LoweredExpr::String(ch.to_string(), Span::generated("static-string-index")))
            .or_else(|| {
                Some(LoweredExpr::Undefined(Span::generated(
                    "static-string-index",
                )))
            }),
        _ => None,
    }
}

fn static_array_element_owned_from_expr_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let key = static_property_key_from_locals_with_functions(locals, key, functions)?;
    let index = key.parse::<usize>().ok()?;
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Array(elements) => elements.get(index).cloned(),
        StaticValue::SparseArray(slots) => {
            Some(
                slots.get(index).cloned().flatten().unwrap_or_else(|| {
                    LoweredExpr::Undefined(Span::generated("sparse-array-hole"))
                }),
            )
        }
        _ => None,
    }
}

fn static_array_dynamic_property_value_from_locals_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &LoweredExpr,
    span: Span,
    functions: &[LoweredFunction],
) -> Option<LoweredExpr> {
    let key = static_property_key_from_locals_with_functions(locals, key, functions)?;
    let value = static_value_from_expr_with_functions(obj, locals, functions)?;
    let elements = match value {
        StaticValue::Array(elements) => elements,
        StaticValue::SparseArray(slots) => materialize_static_sparse_array_slots(&slots, span),
        _ => return None,
    };
    if key == "length" {
        return Some(LoweredExpr::Number(elements.len() as i32, span));
    }
    if let Ok(index) = key.parse::<usize>()
        && key == index.to_string()
    {
        return Some(
            elements
                .get(index)
                .cloned()
                .unwrap_or(LoweredExpr::Undefined(span)),
        );
    }
    Some(LoweredExpr::Undefined(span))
}

fn canonical_static_array_index(key: &str) -> Option<usize> {
    // ES spec: an array index is ToString(ToUint32(P)) == P AND P != 2^32-1.
    let index = key.parse::<u32>().ok()?;
    if index == u32::MAX {
        return None;
    }
    // Practical limit: don't statically track arrays beyond this size.
    // Prevents OOM from Vec::resize_with for large indices like 4294967294.
    if index as usize > MAX_STATIC_ARRAY_ELEMENTS {
        return None;
    }
    (key == index.to_string()).then_some(index as usize)
}

fn static_array_len_from_expr_with_functions(
    expr: &LoweredExpr,
    locals: &HashMap<LocalId, StaticValue>,
    functions: &[LoweredFunction],
) -> Option<usize> {
    match static_value_from_expr_with_functions(expr, locals, functions)? {
        StaticValue::Array(elements) => Some(elements.len()),
        StaticValue::SparseArray(slots) => Some(slots.len()),
        _ => None,
    }
}

fn static_bool_property_from_expr(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<bool> {
    let value = static_object_property_owned_from_expr_with_functions(locals, obj, key, functions)?;
    match static_value_from_expr_with_functions(&value, locals, functions) {
        Some(StaticValue::Primitive(LoweredExpr::Bool(value, _))) => Some(value),
        _ => match &value {
            LoweredExpr::Bool(value, _) => Some(*value),
            _ => None,
        },
    }
}

fn static_descriptor_bool_matches(
    locals: &HashMap<LocalId, StaticValue>,
    descriptor: &LoweredExpr,
    key: &str,
    actual: bool,
    functions: &[LoweredFunction],
) -> bool {
    match static_object_property_owned_from_expr_with_functions(locals, descriptor, key, functions)
    {
        Some(LoweredExpr::Undefined(_)) => true,
        Some(_) => {
            static_bool_property_from_expr(locals, descriptor, key, functions) == Some(actual)
        }
        None => true,
    }
}

fn static_property_is_enumerable_from_expr(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
    key: &str,
    functions: &[LoweredFunction],
) -> Option<bool> {
    match static_value_from_expr_with_functions(obj, locals, functions)? {
        StaticValue::Object(object) => Some(
            object
                .descriptor(key)
                .is_some_and(|(_, attrs)| attrs.enumerable),
        ),
        StaticValue::ObjectAlias(local) => Some(
            static_object_value_from_root(locals, local)?
                .descriptor(key)
                .is_some_and(|(_, attrs)| attrs.enumerable),
        ),
        StaticValue::Array(elements) => {
            if key == "length" {
                return Some(false);
            }
            let index = key.parse::<usize>().ok()?;
            Some(index < elements.len())
        }
        StaticValue::SparseArray(slots) => {
            if key == "length" {
                return Some(false);
            }
            let index = canonical_static_array_index(key)?;
            Some(slots.get(index).is_some_and(Option::is_some))
        }
        StaticValue::Primitive(_)
        | StaticValue::Closure { .. }
        | StaticValue::ArrayPushManyClosure
        | StaticValue::ArrayIterator { .. }
        | StaticValue::Generator { .. }
        | StaticValue::ArrayBuffer(_)
        | StaticValue::DataView { .. }
        | StaticValue::DateObject(_)
        | StaticValue::Symbol(_)
        | StaticValue::TaggedString
        | StaticValue::TaggedNumber
        | StaticValue::TaggedRuntimeValue => None,
    }
}

fn static_object_dynamic_property<'a>(
    ctx: &'a FunctionCtx,
    obj: &'a LoweredExpr,
    key: &'a LoweredExpr,
) -> Option<&'a LoweredExpr> {
    let key = static_property_key_from_locals(&ctx.static_locals, key)?;
    static_object_property_from_locals(&ctx.static_locals, obj, &key)
}

fn static_object_dynamic_property_from_locals_with_functions<'a>(
    locals: &'a HashMap<LocalId, StaticValue>,
    obj: &'a LoweredExpr,
    key: &'a LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<&'a LoweredExpr> {
    let key = static_property_key_from_locals_with_functions(locals, key, functions)?;
    static_object_property_from_locals(locals, obj, &key)
}

fn static_object_known(ctx: &FunctionCtx, obj: &LoweredExpr) -> bool {
    static_object_known_in_locals(&ctx.static_locals, obj)
}

fn static_object_known_in_locals(
    locals: &HashMap<LocalId, StaticValue>,
    obj: &LoweredExpr,
) -> bool {
    if matches!(obj, LoweredExpr::ClassPrototype(_, _)) {
        return true;
    }
    let LoweredExpr::Local(local, _) = obj else {
        return false;
    };
    resolve_static_object_root(locals, *local).is_some()
}

fn static_property_key(key: &LoweredExpr) -> Option<String> {
    match key {
        LoweredExpr::String(value, _) => Some(value.clone()),
        LoweredExpr::Number(value, _) => Some(static_number_property_key(*value)),
        LoweredExpr::DecimalNumber(value, _) => Some(value.clone()),
        LoweredExpr::BigIntLiteral { decimal, sign, .. } => {
            Some(static_bigint_decimal_string(decimal, *sign))
        }
        LoweredExpr::Bool(value, _) => Some(value.to_string()),
        LoweredExpr::Null(_) => Some("null".to_owned()),
        LoweredExpr::Undefined(_) => Some("undefined".to_owned()),
        _ => None,
    }
}

fn static_property_key_from_locals(
    locals: &HashMap<LocalId, StaticValue>,
    key: &LoweredExpr,
) -> Option<String> {
    static_property_key_from_locals_with_functions(locals, key, &[])
}

fn static_property_key_from_locals_with_functions(
    locals: &HashMap<LocalId, StaticValue>,
    key: &LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<String> {
    match key {
        LoweredExpr::Local(local, _) => match locals.get(local) {
            Some(StaticValue::Primitive(value)) => {
                static_property_key_from_locals_with_functions(locals, value, functions)
            }
            Some(StaticValue::Symbol(symbol)) => Some(static_symbol_property_key(symbol.identity)),
            _ => None,
        },
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::ErrorMessage,
            args,
            ..
        } if args.len() == 1 => {
            static_property_key_from_locals_with_functions(locals, &args[0], functions)
        }
        _ => static_property_key(key).or_else(|| {
            match static_value_from_expr_with_functions(key, locals, functions)? {
                StaticValue::Primitive(value) => static_property_key(&value),
                StaticValue::Symbol(symbol) => Some(static_symbol_property_key(symbol.identity)),
                _ => None,
            }
        }),
    }
}

fn static_symbol_property_key(symbol: LocalId) -> String {
    format!("@@symbol:{}", symbol.0)
}

fn static_symbol_property_local(key: &str) -> Option<LocalId> {
    key.strip_prefix("@@symbol:")?.parse().ok().map(LocalId)
}

fn static_number_property_key(value: i32) -> String {
    if value == ValueTag::encode_infinity() {
        "Infinity".to_owned()
    } else if value == ValueTag::encode_neg_infinity() {
        "-Infinity".to_owned()
    } else if value == ValueTag::encode_nan() {
        "NaN".to_owned()
    } else if value == ValueTag::encode_neg_zero() {
        "0".to_owned()
    } else {
        value.to_string()
    }
}

fn static_array_element<'a>(
    ctx: &'a FunctionCtx,
    obj: &'a LoweredExpr,
    key: &'a LoweredExpr,
) -> Option<&'a LoweredExpr> {
    static_array_element_from_locals(&ctx.static_locals, obj, key)
}

fn static_array_property<'a>(
    ctx: &'a FunctionCtx,
    obj: &'a LoweredExpr,
    key: &str,
) -> Option<&'a LoweredExpr> {
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let Some(StaticValue::Array(elements)) = ctx.static_locals.get(local) else {
        return None;
    };
    let index = key.parse::<usize>().ok()?;
    elements.get(index)
}

fn static_array_element_from_locals<'a>(
    locals: &'a HashMap<LocalId, StaticValue>,
    obj: &'a LoweredExpr,
    key: &'a LoweredExpr,
) -> Option<&'a LoweredExpr> {
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let Some(StaticValue::Array(elements)) = locals.get(local) else {
        return None;
    };
    let LoweredExpr::Number(index, _) = key else {
        return None;
    };
    elements.get(*index as usize)
}

fn static_accessor_get_key(functions: &[LoweredFunction], func_id: FuncId) -> Option<String> {
    let function = functions.iter().find(|function| function.id == func_id)?;
    let receiver = *function.params.first()?;
    let returns = function.body.iter().find_map(|stmt| match stmt {
        LoweredStmt::Return(expr, _) => Some(expr),
        _ => None,
    })?;
    receiver_property_get_key(returns, receiver)
}

fn static_accessor_set_key(functions: &[LoweredFunction], func_id: FuncId) -> Option<String> {
    let function = functions.iter().find(|function| function.id == func_id)?;
    let receiver = *function.params.first()?;
    for stmt in &function.body {
        if let Some(key) = receiver_property_set_key_from_stmt(stmt, receiver) {
            return Some(key);
        }
    }
    None
}

fn static_array_push_many_wrapper(functions: &[LoweredFunction], func_id: FuncId) -> bool {
    let Some(function) = functions.iter().find(|function| function.id == func_id) else {
        return false;
    };
    if function.params.len() < 2 {
        return false;
    }
    function
        .body
        .iter()
        .any(|stmt| static_array_push_many_wrapper_stmt(stmt, &function.params))
}

fn static_array_push_many_wrapper_stmt(stmt: &LoweredStmt, params: &[LocalId]) -> bool {
    match stmt {
        LoweredStmt::Expr(expr, _) | LoweredStmt::Return(expr, _) => {
            static_array_push_many_wrapper_expr(expr, params)
        }
        LoweredStmt::Block(stmts, _) => stmts
            .iter()
            .any(|stmt| static_array_push_many_wrapper_stmt(stmt, params)),
        _ => false,
    }
}

fn static_array_push_many_wrapper_expr(expr: &LoweredExpr, params: &[LocalId]) -> bool {
    match expr {
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::ArrayPushMany,
            args,
            ..
        } if args.len() == params.len() => args
            .iter()
            .zip(params.iter())
            .all(|(arg, param)| matches!(arg, LoweredExpr::Local(local, _) if local == param)),
        LoweredExpr::Block { stmts, result, .. } => {
            stmts
                .iter()
                .any(|stmt| static_array_push_many_wrapper_stmt(stmt, params))
                || static_array_push_many_wrapper_expr(result, params)
        }
        _ => false,
    }
}

fn static_array_push_many_bound_closure_expr(expr: &LoweredExpr) -> bool {
    match expr {
        LoweredExpr::Block { stmts, result, .. } => {
            static_array_push_many_bound_closure_result(result, Some(stmts))
        }
        _ => static_array_push_many_bound_closure_result(expr, None),
    }
}

fn static_array_push_many_bound_closure_result(
    expr: &LoweredExpr,
    stmts: Option<&[LoweredStmt]>,
) -> bool {
    let LoweredExpr::RuntimeCall {
        intrinsic: RuntimeFn::HeapClosureCall,
        args,
        ..
    } = expr
    else {
        return false;
    };
    let [
        LoweredExpr::PropertyGet { obj, key, .. },
        receiver,
        LoweredExpr::Number(0, _),
    ] = args.as_slice()
    else {
        return false;
    };
    if key != "bind" {
        return false;
    }
    let LoweredExpr::Local(receiver, _) = receiver else {
        return false;
    };
    let LoweredExpr::Local(obj, _) = obj.as_ref() else {
        return false;
    };
    if obj != receiver {
        return false;
    }
    stmts.is_some_and(|stmts| static_local_is_function_call_property(stmts, *receiver))
}

fn static_object_prototype_method_wrapper(
    functions: &[LoweredFunction],
    func_id: FuncId,
) -> Option<RuntimeFn> {
    let function = functions.iter().find(|function| function.id == func_id)?;
    if function.params.len() < 2 {
        return None;
    }
    let returns = function.body.iter().find_map(|stmt| match stmt {
        LoweredStmt::Return(expr, _) => Some(expr),
        _ => None,
    })?;
    static_object_prototype_method_wrapper_expr(returns, &function.params)
}

fn static_object_prototype_method_wrapper_expr(
    expr: &LoweredExpr,
    params: &[LocalId],
) -> Option<RuntimeFn> {
    let LoweredExpr::RuntimeCall {
        intrinsic: RuntimeFn::HeapClosureCall,
        args,
        ..
    } = expr
    else {
        return None;
    };
    let [method, receiver, key] = args.as_slice() else {
        return None;
    };
    if !matches!(receiver, LoweredExpr::Local(local, _) if *local == params[0])
        || !matches!(key, LoweredExpr::Local(local, _) if *local == params[1])
    {
        return None;
    }
    static_object_prototype_method_expr(method)
}

fn static_object_prototype_method_expr(expr: &LoweredExpr) -> Option<RuntimeFn> {
    let LoweredExpr::Block { stmts, result, .. } = expr else {
        return None;
    };
    let LoweredExpr::PropertyGet { obj, key, .. } = result.as_ref() else {
        return None;
    };
    let LoweredExpr::Local(receiver, _) = obj.as_ref() else {
        return None;
    };
    if !static_local_is_runtime_call_result(stmts, *receiver, RuntimeFn::ObjectPrototype) {
        return None;
    }
    match key.as_str() {
        "hasOwnProperty" => Some(RuntimeFn::ObjectHasOwnProperty),
        "propertyIsEnumerable" => Some(RuntimeFn::PropertyIsEnumerable),
        "toString" => Some(RuntimeFn::ObjectToString),
        _ => None,
    }
}

fn static_local_is_runtime_call_result(
    stmts: &[LoweredStmt],
    local: LocalId,
    intrinsic: RuntimeFn,
) -> bool {
    stmts.iter().any(|stmt| {
        let (LoweredStmt::Let(candidate, expr, _) | LoweredStmt::Assign(candidate, expr, _)) = stmt
        else {
            return false;
        };
        *candidate == local
            && matches!(
                expr,
                LoweredExpr::RuntimeCall {
                    intrinsic: expr_intrinsic,
                    args,
                    ..
                } if *expr_intrinsic == intrinsic && args.is_empty()
            )
    })
}

fn static_array_join_wrapper(functions: &[LoweredFunction], func_id: FuncId) -> bool {
    let Some(function) = functions.iter().find(|function| function.id == func_id) else {
        return false;
    };
    if function.params.len() < 2 {
        return false;
    }
    let Some(returns) = function.body.iter().find_map(|stmt| match stmt {
        LoweredStmt::Return(expr, _) => Some(expr),
        _ => None,
    }) else {
        return false;
    };
    let LoweredExpr::RuntimeCall {
        intrinsic: RuntimeFn::HeapClosureCall,
        args,
        ..
    } = returns
    else {
        return false;
    };
    let [method, receiver, separator] = args.as_slice() else {
        return false;
    };
    static_array_join_method_expr(method).is_some()
        && matches!(receiver, LoweredExpr::Local(local, _) if *local == function.params[0])
        && matches!(separator, LoweredExpr::Local(local, _) if *local == function.params[1])
}

fn static_array_index_equal_callback(functions: &[LoweredFunction], func_id: FuncId) -> bool {
    let Some(function) = functions.iter().find(|function| function.id == func_id) else {
        return false;
    };
    if function.params.len() < 3 {
        return false;
    }
    function.body.iter().any(|stmt| {
        let LoweredStmt::If {
            condition,
            then_body,
            ..
        } = stmt
        else {
            return false;
        };
        let LoweredExpr::Binary {
            left,
            op: LoweredBinaryOp::StrictEqual,
            right,
            ..
        } = condition
        else {
            return false;
        };
        static_array_index_equal_callback_left(left, function.params[2], function.params[1])
            && matches!(right.as_ref(), LoweredExpr::Local(local, _) if *local == function.params[0])
            && then_body
                .iter()
                .any(|stmt| matches!(stmt, LoweredStmt::Return(LoweredExpr::Bool(true, _), _)))
    })
}

fn static_array_index_equal_callback_left(
    expr: &LoweredExpr,
    array_param: LocalId,
    index_param: LocalId,
) -> bool {
    match expr {
        LoweredExpr::PropertyGetDynamic { obj, key, .. }
        | LoweredExpr::Index {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::OptionalIndex {
            object: obj,
            index: key,
            ..
        } => {
            matches!(obj.as_ref(), LoweredExpr::Local(local, _) if *local == array_param)
                && matches!(key.as_ref(), LoweredExpr::Local(local, _) if *local == index_param)
        }
        LoweredExpr::Block { stmts, result, .. } => {
            let aliases = receiver_aliases(stmts, array_param);
            match result.as_ref() {
                LoweredExpr::PropertyGetDynamic { obj, key, .. }
                | LoweredExpr::Index {
                    object: obj,
                    index: key,
                    ..
                }
                | LoweredExpr::OptionalIndex {
                    object: obj,
                    index: key,
                    ..
                } => {
                    receiver_or_alias_expr_matches(obj, array_param, &aliases)
                        && matches!(key.as_ref(), LoweredExpr::Local(local, _) if *local == index_param)
                }
                _ => false,
            }
        }
        _ => false,
    }
}

fn static_array_join_method_expr(expr: &LoweredExpr) -> Option<()> {
    let LoweredExpr::Block { stmts, result, .. } = expr else {
        return None;
    };
    let LoweredExpr::PropertyGet { obj, key, .. } = result.as_ref() else {
        return None;
    };
    if key != "join" {
        return None;
    }
    let LoweredExpr::Local(receiver, _) = obj.as_ref() else {
        return None;
    };
    static_local_is_array_prototype_expr(stmts, *receiver).then_some(())
}

fn static_local_is_array_prototype_expr(stmts: &[LoweredStmt], local: LocalId) -> bool {
    stmts.iter().any(|stmt| {
        let (LoweredStmt::Let(candidate, expr, _) | LoweredStmt::Assign(candidate, expr, _)) = stmt
        else {
            return false;
        };
        *candidate == local && static_expr_is_prototype_get(expr)
    })
}

fn static_expr_is_prototype_get(expr: &LoweredExpr) -> bool {
    match expr {
        LoweredExpr::PropertyGet { key, .. } => key == "prototype",
        LoweredExpr::Block { result, .. } => static_expr_is_prototype_get(result),
        _ => false,
    }
}

fn static_local_is_function_call_property(stmts: &[LoweredStmt], local: LocalId) -> bool {
    stmts.iter().any(|stmt| {
        let (LoweredStmt::Let(candidate, expr, _) | LoweredStmt::Assign(candidate, expr, _)) = stmt
        else {
            return false;
        };
        *candidate == local && static_expr_is_function_call_property(expr)
    })
}

fn static_expr_is_function_call_property(expr: &LoweredExpr) -> bool {
    match expr {
        LoweredExpr::PropertyGet { key, .. } => key == "call",
        LoweredExpr::Block { result, .. } => static_expr_is_function_call_property(result),
        _ => false,
    }
}

fn receiver_property_get_key(expr: &LoweredExpr, receiver: LocalId) -> Option<String> {
    match expr {
        LoweredExpr::PropertyGet { obj, key, .. } if receiver_expr_matches(obj, receiver) => {
            Some(key.clone())
        }
        LoweredExpr::Block { stmts, result, .. } => {
            let aliases = receiver_aliases(stmts, receiver);
            let LoweredExpr::PropertyGet { obj, key, .. } = result.as_ref() else {
                return None;
            };
            receiver_or_alias_expr_matches(obj, receiver, &aliases).then(|| key.clone())
        }
        _ => None,
    }
}

fn receiver_property_set_key_from_stmt(stmt: &LoweredStmt, receiver: LocalId) -> Option<String> {
    match stmt {
        LoweredStmt::Expr(expr, _) => receiver_property_set_key(expr, receiver),
        LoweredStmt::Block(stmts, _) => {
            for stmt in stmts {
                if let Some(key) = receiver_property_set_key_from_stmt(stmt, receiver) {
                    return Some(key);
                }
            }
            None
        }
        _ => None,
    }
}

fn receiver_property_set_key(expr: &LoweredExpr, receiver: LocalId) -> Option<String> {
    match expr {
        LoweredExpr::PropertySet { object, key, .. } if receiver_expr_matches(object, receiver) => {
            Some(key.clone())
        }
        LoweredExpr::Block { stmts, result, .. } => {
            let aliases = receiver_aliases(stmts, receiver);
            let LoweredExpr::PropertySet { object, key, .. } = result.as_ref() else {
                return None;
            };
            receiver_or_alias_expr_matches(object, receiver, &aliases).then(|| key.clone())
        }
        _ => None,
    }
}

fn receiver_aliases(stmts: &[LoweredStmt], receiver: LocalId) -> HashSet<LocalId> {
    let mut aliases = HashSet::new();
    for stmt in stmts {
        if let LoweredStmt::Let(local, expr, _) | LoweredStmt::Assign(local, expr, _) = stmt
            && receiver_or_alias_expr_matches(expr, receiver, &aliases)
        {
            aliases.insert(*local);
        }
    }
    aliases
}

fn receiver_expr_matches(expr: &LoweredExpr, receiver: LocalId) -> bool {
    matches!(expr, LoweredExpr::Local(local, _) if *local == receiver)
}

fn receiver_or_alias_expr_matches(
    expr: &LoweredExpr,
    receiver: LocalId,
    aliases: &HashSet<LocalId>,
) -> bool {
    match expr {
        LoweredExpr::Local(local, _) => *local == receiver || aliases.contains(local),
        _ => false,
    }
}

fn collect_runtime_required_functions(program: &LoweredProgram) -> HashSet<FuncId> {
    let mut required = HashSet::new();
    let mut visiting = HashSet::new();

    let mut top_level_locals = HashMap::new();
    collect_runtime_required_from_stmts(
        &program.top_level_statements,
        &program.functions,
        &mut top_level_locals,
        &mut required,
        &mut visiting,
    );

    for module in &program.modules {
        let mut module_locals = HashMap::new();
        collect_runtime_required_from_stmts(
            &module.statements,
            &program.functions,
            &mut module_locals,
            &mut required,
            &mut visiting,
        );
    }

    if program_contains_heap_closure_call(program) {
        for function in &program.functions {
            mark_runtime_required_function(
                function.id,
                &program.functions,
                &mut required,
                &mut visiting,
            );
        }
    }

    required
}

fn program_contains_heap_closure_call(program: &LoweredProgram) -> bool {
    stmts_contain_heap_closure_call(&program.top_level_statements)
        || program
            .modules
            .iter()
            .any(|module| stmts_contain_heap_closure_call(&module.statements))
        || program
            .functions
            .iter()
            .any(|function| stmts_contain_heap_closure_call(&function.body))
}

fn stmts_contain_heap_closure_call(stmts: &[LoweredStmt]) -> bool {
    stmts.iter().any(stmt_contains_heap_closure_call)
}

fn stmt_contains_heap_closure_call(stmt: &LoweredStmt) -> bool {
    match stmt {
        LoweredStmt::Let(_, expr, _)
        | LoweredStmt::Assign(_, expr, _)
        | LoweredStmt::Expr(expr, _)
        | LoweredStmt::Yield(expr, _)
        | LoweredStmt::Return(expr, _)
        | LoweredStmt::Throw(expr, _)
        | LoweredStmt::Export { expr, .. }
        | LoweredStmt::ModuleExportsAssign { expr, .. } => expr_contains_heap_closure_call(expr),
        LoweredStmt::Block(stmts, _) => stmts_contain_heap_closure_call(stmts),
        LoweredStmt::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            expr_contains_heap_closure_call(condition)
                || stmts_contain_heap_closure_call(then_body)
                || stmts_contain_heap_closure_call(else_body)
        }
        LoweredStmt::While {
            condition, body, ..
        }
        | LoweredStmt::DoWhile {
            condition, body, ..
        } => expr_contains_heap_closure_call(condition) || stmts_contain_heap_closure_call(body),
        LoweredStmt::For {
            init,
            condition,
            update,
            body,
            ..
        } => {
            init.as_deref().is_some_and(stmt_contains_heap_closure_call)
                || condition
                    .as_ref()
                    .is_some_and(expr_contains_heap_closure_call)
                || update.as_ref().is_some_and(expr_contains_heap_closure_call)
                || stmts_contain_heap_closure_call(body)
        }
        LoweredStmt::ForIn { iter, .. } => expr_contains_heap_closure_call(iter),
        LoweredStmt::ForOf { iter, body, .. } => {
            expr_contains_heap_closure_call(iter) || stmts_contain_heap_closure_call(body)
        }
        LoweredStmt::ForAwaitOfLower { iter, body, .. } => {
            expr_contains_heap_closure_call(iter) || stmts_contain_heap_closure_call(body)
        }
        LoweredStmt::Switch { expr, cases, .. } => {
            expr_contains_heap_closure_call(expr)
                || cases.iter().any(|(case_expr, body)| {
                    case_expr
                        .as_ref()
                        .is_some_and(expr_contains_heap_closure_call)
                        || stmts_contain_heap_closure_call(body)
                })
        }
        LoweredStmt::TryFinally {
            try_body,
            finally_body,
            ..
        } => {
            stmts_contain_heap_closure_call(try_body)
                || stmts_contain_heap_closure_call(finally_body)
        }
        LoweredStmt::TryCatch {
            try_body,
            catch_body,
            finally_body,
            ..
        } => {
            stmts_contain_heap_closure_call(try_body)
                || catch_body
                    .as_ref()
                    .is_some_and(|body| stmts_contain_heap_closure_call(body))
                || finally_body
                    .as_ref()
                    .is_some_and(|body| stmts_contain_heap_closure_call(body))
        }
        LoweredStmt::Labeled { body, .. } => stmt_contains_heap_closure_call(body),
        LoweredStmt::ModuleExportsUpdate { .. }
        | LoweredStmt::ClassDecl { .. }
        | LoweredStmt::Break { .. }
        | LoweredStmt::Continue { .. } => false,
    }
}

fn expr_contains_heap_closure_call(expr: &LoweredExpr) -> bool {
    match expr {
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::HeapClosureCall,
            ..
        } => true,
        LoweredExpr::RuntimeCall { args, .. } | LoweredExpr::Call { args, .. } => {
            args.iter().any(expr_contains_heap_closure_call)
        }
        LoweredExpr::Block { stmts, result, .. } => {
            stmts_contain_heap_closure_call(stmts) || expr_contains_heap_closure_call(result)
        }
        LoweredExpr::Unary { expr, .. }
        | LoweredExpr::Assign { expr, .. }
        | LoweredExpr::LogicalAssign { expr, .. }
        | LoweredExpr::PromiseGetValue { promise: expr, .. }
        | LoweredExpr::GetLength(expr, _) => expr_contains_heap_closure_call(expr),
        LoweredExpr::Binary { left, right, .. } => {
            expr_contains_heap_closure_call(left) || expr_contains_heap_closure_call(right)
        }
        LoweredExpr::PropertyGet { obj, .. } | LoweredExpr::OptionalPropertyGet { obj, .. } => {
            expr_contains_heap_closure_call(obj)
        }
        LoweredExpr::PropertySet { object, value, .. } => {
            expr_contains_heap_closure_call(object) || expr_contains_heap_closure_call(value)
        }
        LoweredExpr::PropertyGetDynamic { obj, key, .. }
        | LoweredExpr::OptionalIndex {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::Index {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::ArrayGet {
            arr: obj,
            index: key,
            ..
        } => expr_contains_heap_closure_call(obj) || expr_contains_heap_closure_call(key),
        LoweredExpr::PropertySetDynamic {
            object,
            index,
            value,
            ..
        } => {
            expr_contains_heap_closure_call(object)
                || expr_contains_heap_closure_call(index)
                || expr_contains_heap_closure_call(value)
        }
        LoweredExpr::LogicalPropertyAssign { expr, .. }
        | LoweredExpr::LogicalComputedPropertyAssign { expr, .. }
        | LoweredExpr::LogicalComputedMemberAssign { expr, .. }
        | LoweredExpr::LogicalMemberAssign { expr, .. } => expr_contains_heap_closure_call(expr),
        LoweredExpr::ObjectNew { props, .. } => props
            .iter()
            .any(|(_, value)| expr_contains_heap_closure_call(value)),
        LoweredExpr::ArrayNew { elements, .. } => {
            elements.iter().any(expr_contains_heap_closure_call)
        }
        LoweredExpr::ArrayNewSparse { slots, .. } => slots.iter().any(|slot| {
            matches!(
                slot,
                ts2wasm_ir::lowered::LoweredArraySlot::Present(expr)
                    if expr_contains_heap_closure_call(expr)
            )
        }),
        LoweredExpr::ErrorNew {
            message,
            cause,
            errors,
            ..
        } => {
            expr_contains_heap_closure_call(message)
                || cause
                    .as_deref()
                    .is_some_and(expr_contains_heap_closure_call)
                || errors
                    .as_deref()
                    .is_some_and(expr_contains_heap_closure_call)
        }
        LoweredExpr::New { args, .. } => args.iter().any(expr_contains_heap_closure_call),
        LoweredExpr::MethodCall { object, .. } => expr_contains_heap_closure_call(object),
        LoweredExpr::OptionalCall { callee, call, .. } => {
            expr_contains_heap_closure_call(callee) || expr_contains_heap_closure_call(call)
        }
        LoweredExpr::PropertyIn { obj, .. } => expr_contains_heap_closure_call(obj),
        LoweredExpr::PropertyInDynamic { obj, key, .. } => {
            expr_contains_heap_closure_call(obj) || expr_contains_heap_closure_call(key)
        }
        LoweredExpr::PropertyDeleteDynamic { object, key, .. } => {
            expr_contains_heap_closure_call(object) || expr_contains_heap_closure_call(key)
        }
        LoweredExpr::EnvCellSet { expr, .. } => expr_contains_heap_closure_call(expr),
        _ => false,
    }
}

fn collect_runtime_required_from_stmts(
    stmts: &[LoweredStmt],
    functions: &[LoweredFunction],
    static_locals: &mut HashMap<LocalId, StaticValue>,
    required: &mut HashSet<FuncId>,
    visiting: &mut HashSet<FuncId>,
) {
    for stmt in stmts {
        collect_runtime_required_from_stmt(stmt, functions, static_locals, required, visiting);
        collect_static_locals_with_functions(std::slice::from_ref(stmt), static_locals, functions);
    }
}

fn collect_runtime_required_from_stmt(
    stmt: &LoweredStmt,
    functions: &[LoweredFunction],
    static_locals: &HashMap<LocalId, StaticValue>,
    required: &mut HashSet<FuncId>,
    visiting: &mut HashSet<FuncId>,
) {
    match stmt {
        LoweredStmt::Let(_, expr, _)
        | LoweredStmt::Assign(_, expr, _)
        | LoweredStmt::Yield(expr, _)
        | LoweredStmt::Return(expr, _) => {
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredStmt::Expr(expr, _) => {
            if !matches!(expr, LoweredExpr::Block { .. })
                && static_stmt_expr_folded(expr, functions, static_locals)
            {
                return;
            }
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredStmt::Block(stmts, _) => {
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(stmts, functions, &mut nested, required, visiting);
        }
        LoweredStmt::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            collect_runtime_required_from_expr(
                condition,
                functions,
                static_locals,
                required,
                visiting,
            );
            let mut then_locals = static_locals.clone();
            collect_runtime_required_from_stmts(
                then_body,
                functions,
                &mut then_locals,
                required,
                visiting,
            );
            let mut else_locals = static_locals.clone();
            collect_runtime_required_from_stmts(
                else_body,
                functions,
                &mut else_locals,
                required,
                visiting,
            );
        }
        LoweredStmt::While {
            condition, body, ..
        }
        | LoweredStmt::DoWhile {
            condition, body, ..
        } => {
            collect_runtime_required_from_expr(
                condition,
                functions,
                static_locals,
                required,
                visiting,
            );
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(body, functions, &mut nested, required, visiting);
        }
        LoweredStmt::For {
            init,
            condition,
            update,
            body,
            ..
        } => {
            let mut nested = static_locals.clone();
            if let Some(init) = init {
                collect_runtime_required_from_stmt(init, functions, &nested, required, visiting);
                collect_static_locals_with_functions(
                    std::slice::from_ref(init),
                    &mut nested,
                    functions,
                );
            }
            if let Some(condition) = condition {
                collect_runtime_required_from_expr(
                    condition, functions, &nested, required, visiting,
                );
            }
            if let Some(update) = update {
                collect_runtime_required_from_expr(update, functions, &nested, required, visiting);
            }
            collect_runtime_required_from_stmts(body, functions, &mut nested, required, visiting);
        }
        LoweredStmt::ForIn { iter, body, .. }
        | LoweredStmt::ForOf { iter, body, .. }
        | LoweredStmt::ForAwaitOfLower { iter, body, .. } => {
            collect_runtime_required_from_expr(iter, functions, static_locals, required, visiting);
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(body, functions, &mut nested, required, visiting);
        }
        LoweredStmt::Switch { expr, cases, .. } => {
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
            for (case_expr, body) in cases {
                let mut nested = static_locals.clone();
                if let Some(case_expr) = case_expr {
                    collect_runtime_required_from_expr(
                        case_expr, functions, &nested, required, visiting,
                    );
                }
                collect_runtime_required_from_stmts(
                    body,
                    functions,
                    &mut nested,
                    required,
                    visiting,
                );
            }
        }
        LoweredStmt::TryFinally {
            try_body,
            finally_body,
            ..
        } => {
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(
                try_body,
                functions,
                &mut nested,
                required,
                visiting,
            );
            collect_runtime_required_from_stmts(
                finally_body,
                functions,
                &mut nested,
                required,
                visiting,
            );
        }
        LoweredStmt::TryCatch {
            try_body,
            catch_body,
            finally_body,
            ..
        } => {
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(
                try_body,
                functions,
                &mut nested,
                required,
                visiting,
            );
            if let Some(catch_body) = catch_body {
                let mut catch_locals = static_locals.clone();
                collect_runtime_required_from_stmts(
                    catch_body,
                    functions,
                    &mut catch_locals,
                    required,
                    visiting,
                );
            }
            if let Some(finally_body) = finally_body {
                collect_runtime_required_from_stmts(
                    finally_body,
                    functions,
                    &mut nested,
                    required,
                    visiting,
                );
            }
        }
        LoweredStmt::Export { expr, .. } | LoweredStmt::ModuleExportsAssign { expr, .. } => {
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredStmt::ModuleExportsUpdate { .. } => {}
        _ => {}
    }
}

fn static_stmt_expr_folded(
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
    static_locals: &HashMap<LocalId, StaticValue>,
) -> bool {
    match expr {
        LoweredExpr::Call {
            kind: FunctionCallKind::Builtin(BuiltinId::ConsoleLog),
            args,
            ..
        } => {
            if args.iter().any(|arg| {
                matches!(
                    arg,
                    LoweredExpr::Block { stmts, .. } if !stmts.is_empty()
                )
            }) {
                return false;
            }
            if args.iter().any(|arg| {
                matches!(
                    arg,
                    LoweredExpr::Call {
                        kind: FunctionCallKind::User(func_id),
                        ..
                    } if static_user_function_has_console_side_effect(
                        functions,
                        *func_id,
                        &mut HashSet::new()
                    )
                )
            }) {
                return false;
            }
            let ctx = static_analysis_ctx(static_locals.clone());
            args.iter().all(|arg| {
                static_console_arg_bytes_with_functions(arg, &ctx, functions).is_some()
                    || static_accessor_get_call_folded(arg, functions, static_locals)
            })
        }
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } if static_accessor_set_key(functions, *func_id).is_some() => {
            static_accessor_receiver_is_static_object(args, static_locals)
        }
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } if static_array_index_equal_callback(functions, *func_id) => {
            static_array_receiver_is_static(args.get(2), static_locals)
        }
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } if static_array_join_wrapper(functions, *func_id) => static_array_join_call_value(
            functions,
            *func_id,
            args,
            Span::generated("static_array_join"),
            static_locals,
        )
        .is_some(),
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } if static_object_prototype_method_wrapper(functions, *func_id).is_some() => {
            static_object_prototype_method_call_value(
                functions,
                *func_id,
                args,
                Span::generated("static_object_prototype_method"),
                static_locals,
            )
            .is_some()
        }
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } => {
            if static_user_function_has_console_side_effect(
                functions,
                *func_id,
                &mut HashSet::new(),
            ) {
                return false;
            }
            if !args
                .iter()
                .all(|arg| static_value_from_expr(arg, static_locals).is_some())
            {
                return false;
            }
            let mut locals = static_locals.clone();
            apply_static_user_function_env_effects(functions, *func_id, args, &mut locals)
        }
        _ => static_value_from_expr_with_functions(expr, static_locals, functions).is_some(),
    }
}

fn function_body_reaches_eval_host_return(
    functions: &[LoweredFunction],
    func_id: FuncId,
    visiting: &mut HashSet<FuncId>,
) -> bool {
    if !visiting.insert(func_id) {
        return false;
    }
    let Some(function) = functions.iter().find(|function| function.id == func_id) else {
        return false;
    };
    function.body.iter().any(|stmt| {
        matches!(
            stmt,
            LoweredStmt::Return(
                LoweredExpr::RuntimeCall {
                    intrinsic: RuntimeFn::EvalDirectHost | RuntimeFn::EvalIndirectHost,
                    ..
                },
                _
            )
        ) || stmt_calls_function_reaching_eval_host(stmt, functions, visiting)
    })
}

fn stmt_calls_function_reaching_eval_host(
    stmt: &LoweredStmt,
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    match stmt {
        LoweredStmt::Let(_, expr, _)
        | LoweredStmt::Assign(_, expr, _)
        | LoweredStmt::Expr(expr, _)
        | LoweredStmt::Yield(expr, _)
        | LoweredStmt::Return(expr, _)
        | LoweredStmt::Throw(expr, _)
        | LoweredStmt::Export { expr, .. }
        | LoweredStmt::ModuleExportsAssign { expr, .. } => {
            expr_calls_function_reaching_eval_host(expr, functions, visiting)
        }
        LoweredStmt::Block(stmts, _) => stmts
            .iter()
            .any(|stmt| stmt_calls_function_reaching_eval_host(stmt, functions, visiting)),
        _ => false,
    }
}

fn expr_calls_function_reaching_eval_host(
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    match expr {
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            args,
            ..
        } => {
            function_body_reaches_eval_host_return(functions, *func_id, visiting)
                || args
                    .iter()
                    .any(|arg| expr_calls_function_reaching_eval_host(arg, functions, visiting))
        }
        LoweredExpr::Call { args, .. } | LoweredExpr::RuntimeCall { args, .. } => args
            .iter()
            .any(|arg| expr_calls_function_reaching_eval_host(arg, functions, visiting)),
        LoweredExpr::Binary { left, right, .. } => {
            expr_calls_function_reaching_eval_host(left, functions, visiting)
                || expr_calls_function_reaching_eval_host(right, functions, visiting)
        }
        LoweredExpr::Unary { expr, .. }
        | LoweredExpr::Assign { expr, .. }
        | LoweredExpr::LogicalAssign { expr, .. }
        | LoweredExpr::EnvCellNew(expr, _)
        | LoweredExpr::EnvCellSet { expr, .. } => {
            expr_calls_function_reaching_eval_host(expr, functions, visiting)
        }
        LoweredExpr::Block { stmts, result, .. } => {
            stmts
                .iter()
                .any(|stmt| stmt_calls_function_reaching_eval_host(stmt, functions, visiting))
                || expr_calls_function_reaching_eval_host(result, functions, visiting)
        }
        _ => false,
    }
}

fn static_accessor_get_call_folded(
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
    static_locals: &HashMap<LocalId, StaticValue>,
) -> bool {
    let LoweredExpr::Call {
        kind: FunctionCallKind::User(func_id),
        args,
        ..
    } = expr
    else {
        return false;
    };
    static_accessor_get_key(functions, *func_id).is_some()
        && static_accessor_receiver_is_static_object(args, static_locals)
}

fn static_accessor_receiver_is_static_object(
    args: &[LoweredExpr],
    static_locals: &HashMap<LocalId, StaticValue>,
) -> bool {
    let Some(LoweredExpr::Local(local, _)) = args.first() else {
        return false;
    };
    resolve_static_object_root(static_locals, *local).is_some()
}

fn static_array_receiver_is_static(
    expr: Option<&LoweredExpr>,
    static_locals: &HashMap<LocalId, StaticValue>,
) -> bool {
    let Some(LoweredExpr::Local(local, _)) = expr else {
        return false;
    };
    matches!(static_locals.get(local), Some(StaticValue::Array(_)))
}

fn collect_runtime_required_from_expr(
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
    static_locals: &HashMap<LocalId, StaticValue>,
    required: &mut HashSet<FuncId>,
    visiting: &mut HashSet<FuncId>,
) {
    match expr {
        LoweredExpr::Call { kind, args, .. } => {
            for arg in args {
                collect_runtime_required_from_expr(
                    arg,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
            if let FunctionCallKind::User(func_id) = kind {
                if static_array_index_equal_callback(functions, *func_id)
                    && static_array_receiver_is_static(args.get(2), static_locals)
                {
                    return;
                }
                if static_array_join_wrapper(functions, *func_id)
                    && static_array_join_call_value(
                        functions,
                        *func_id,
                        args,
                        Span::generated("static_array_join"),
                        static_locals,
                    )
                    .is_some()
                {
                    return;
                }
                if static_object_prototype_method_wrapper(functions, *func_id).is_some()
                    && static_object_prototype_method_call_value(
                        functions,
                        *func_id,
                        args,
                        Span::generated("static_object_prototype_method"),
                        static_locals,
                    )
                    .is_some()
                {
                    return;
                }
                mark_runtime_required_function(*func_id, functions, required, visiting);
            }
        }
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::HeapClosureCall,
            args,
            ..
        } => {
            for arg in args {
                collect_runtime_required_from_expr(
                    arg,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
            for function in functions {
                mark_runtime_required_function(function.id, functions, required, visiting);
            }
        }
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::SetPrototypeAddSet,
            args,
            ..
        } => {
            for arg in args {
                collect_runtime_required_from_expr(
                    arg,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
            if let [LoweredExpr::Number(id, _)] = args.as_slice()
                && *id >= 0
            {
                mark_runtime_required_function(FuncId(*id as usize), functions, required, visiting);
            }
        }
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::PromiseThen | RuntimeFn::PromiseCatch,
            args,
            ..
        } => {
            for arg in args {
                collect_runtime_required_from_expr(
                    arg,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
            for function in functions {
                mark_runtime_required_function(function.id, functions, required, visiting);
            }
        }
        LoweredExpr::RuntimeCall { args, .. } => {
            for arg in args {
                collect_runtime_required_from_expr(
                    arg,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
        }
        LoweredExpr::Block { stmts, result, .. } => {
            let mut nested = static_locals.clone();
            collect_runtime_required_from_stmts(stmts, functions, &mut nested, required, visiting);
            collect_runtime_required_from_expr(result, functions, &nested, required, visiting);
        }
        LoweredExpr::Binary { left, right, .. } => {
            collect_runtime_required_from_expr(left, functions, static_locals, required, visiting);
            collect_runtime_required_from_expr(right, functions, static_locals, required, visiting);
        }
        LoweredExpr::Unary { expr, .. }
        | LoweredExpr::Assign { expr, .. }
        | LoweredExpr::LogicalAssign { expr, .. }
        | LoweredExpr::PromiseGetValue { promise: expr, .. }
        | LoweredExpr::GetLength(expr, _) => {
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredExpr::LogicalPropertyAssign { expr, .. } => {
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredExpr::LogicalComputedPropertyAssign { key, expr, .. } => {
            collect_runtime_required_from_expr(key, functions, static_locals, required, visiting);
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredExpr::LogicalMemberAssign { object, expr, .. } => {
            collect_runtime_required_from_expr(
                object,
                functions,
                static_locals,
                required,
                visiting,
            );
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredExpr::LogicalComputedMemberAssign {
            object, key, expr, ..
        } => {
            collect_runtime_required_from_expr(
                object,
                functions,
                static_locals,
                required,
                visiting,
            );
            collect_runtime_required_from_expr(key, functions, static_locals, required, visiting);
            collect_runtime_required_from_expr(expr, functions, static_locals, required, visiting);
        }
        LoweredExpr::PropertyGet { obj, .. } | LoweredExpr::OptionalPropertyGet { obj, .. } => {
            collect_runtime_required_from_expr(obj, functions, static_locals, required, visiting);
        }
        LoweredExpr::PropertySet { object, value, .. } => {
            collect_runtime_required_from_expr(
                object,
                functions,
                static_locals,
                required,
                visiting,
            );
            collect_runtime_required_from_expr(value, functions, static_locals, required, visiting);
        }
        LoweredExpr::PropertyGetDynamic { obj, key, .. }
        | LoweredExpr::OptionalIndex {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::Index {
            object: obj,
            index: key,
            ..
        } => {
            collect_runtime_required_from_expr(obj, functions, static_locals, required, visiting);
            collect_runtime_required_from_expr(key, functions, static_locals, required, visiting);
        }
        LoweredExpr::PropertySetDynamic {
            object,
            index,
            value,
            ..
        } => {
            collect_runtime_required_from_expr(
                object,
                functions,
                static_locals,
                required,
                visiting,
            );
            collect_runtime_required_from_expr(index, functions, static_locals, required, visiting);
            collect_runtime_required_from_expr(value, functions, static_locals, required, visiting);
        }
        LoweredExpr::ObjectNew { props, .. } => {
            for (_, value) in props {
                collect_runtime_required_from_expr(
                    value,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
        }
        LoweredExpr::ArrayNew { elements, .. } => {
            for element in elements {
                collect_runtime_required_from_expr(
                    element,
                    functions,
                    static_locals,
                    required,
                    visiting,
                );
            }
        }
        _ => {}
    }
}

fn mark_runtime_required_function(
    func_id: FuncId,
    functions: &[LoweredFunction],
    required: &mut HashSet<FuncId>,
    visiting: &mut HashSet<FuncId>,
) {
    if !required.insert(func_id) || !visiting.insert(func_id) {
        return;
    }
    let Some(function) = functions.iter().find(|function| function.id == func_id) else {
        visiting.remove(&func_id);
        return;
    };
    let mut static_locals = HashMap::new();
    collect_runtime_required_from_stmts(
        &function.body,
        functions,
        &mut static_locals,
        required,
        visiting,
    );
    visiting.remove(&func_id);
}

fn collect_set_prototype_add_direct_function_ids(program: &LoweredProgram) -> Vec<FuncId> {
    let mut ids = HashSet::new();
    collect_set_prototype_add_direct_function_ids_from_stmts(
        &program.top_level_statements,
        &mut ids,
    );
    for module in &program.modules {
        collect_set_prototype_add_direct_function_ids_from_stmts(&module.statements, &mut ids);
    }
    for function in &program.functions {
        collect_set_prototype_add_direct_function_ids_from_stmts(&function.body, &mut ids);
    }
    let function_ids = program
        .functions
        .iter()
        .map(|function| function.id)
        .collect::<HashSet<_>>();
    let mut ids = ids
        .into_iter()
        .filter(|id| function_ids.contains(id))
        .collect::<Vec<_>>();
    ids.sort_by_key(|id| id.0);
    ids
}

fn collect_set_prototype_add_direct_function_ids_from_stmts(
    stmts: &[LoweredStmt],
    ids: &mut HashSet<FuncId>,
) {
    for stmt in stmts {
        match stmt {
            LoweredStmt::Let(_, expr, _)
            | LoweredStmt::Assign(_, expr, _)
            | LoweredStmt::Expr(expr, _)
            | LoweredStmt::Yield(expr, _)
            | LoweredStmt::Return(expr, _)
            | LoweredStmt::Throw(expr, _) => {
                collect_set_prototype_add_direct_function_ids_from_expr(expr, ids);
            }
            LoweredStmt::Block(stmts, _) => {
                collect_set_prototype_add_direct_function_ids_from_stmts(stmts, ids);
            }
            LoweredStmt::Labeled { body, .. } => {
                collect_set_prototype_add_direct_function_ids_from_stmts(
                    std::slice::from_ref(body),
                    ids,
                );
            }
            LoweredStmt::If {
                condition,
                then_body,
                else_body,
                ..
            } => {
                collect_set_prototype_add_direct_function_ids_from_expr(condition, ids);
                collect_set_prototype_add_direct_function_ids_from_stmts(then_body, ids);
                collect_set_prototype_add_direct_function_ids_from_stmts(else_body, ids);
            }
            LoweredStmt::While {
                condition, body, ..
            }
            | LoweredStmt::DoWhile {
                condition, body, ..
            } => {
                collect_set_prototype_add_direct_function_ids_from_expr(condition, ids);
                collect_set_prototype_add_direct_function_ids_from_stmts(body, ids);
            }
            LoweredStmt::For {
                init,
                condition,
                update,
                body,
                ..
            } => {
                if let Some(init) = init {
                    collect_set_prototype_add_direct_function_ids_from_stmts(
                        std::slice::from_ref(init),
                        ids,
                    );
                }
                if let Some(condition) = condition {
                    collect_set_prototype_add_direct_function_ids_from_expr(condition, ids);
                }
                if let Some(update) = update {
                    collect_set_prototype_add_direct_function_ids_from_expr(update, ids);
                }
                collect_set_prototype_add_direct_function_ids_from_stmts(body, ids);
            }
            LoweredStmt::ForIn { iter, body, .. } | LoweredStmt::ForOf { iter, body, .. } => {
                collect_set_prototype_add_direct_function_ids_from_expr(iter, ids);
                collect_set_prototype_add_direct_function_ids_from_stmts(body, ids);
            }
            LoweredStmt::Switch { expr, cases, .. } => {
                collect_set_prototype_add_direct_function_ids_from_expr(expr, ids);
                for (case_expr, body) in cases {
                    if let Some(case_expr) = case_expr {
                        collect_set_prototype_add_direct_function_ids_from_expr(case_expr, ids);
                    }
                    collect_set_prototype_add_direct_function_ids_from_stmts(body, ids);
                }
            }
            LoweredStmt::TryFinally {
                try_body,
                finally_body,
                ..
            } => {
                collect_set_prototype_add_direct_function_ids_from_stmts(try_body, ids);
                collect_set_prototype_add_direct_function_ids_from_stmts(finally_body, ids);
            }
            LoweredStmt::TryCatch {
                try_body,
                catch_body,
                finally_body,
                ..
            } => {
                collect_set_prototype_add_direct_function_ids_from_stmts(try_body, ids);
                if let Some(catch_body) = catch_body {
                    collect_set_prototype_add_direct_function_ids_from_stmts(catch_body, ids);
                }
                if let Some(finally_body) = finally_body {
                    collect_set_prototype_add_direct_function_ids_from_stmts(finally_body, ids);
                }
            }
            LoweredStmt::Export { expr, .. } | LoweredStmt::ModuleExportsAssign { expr, .. } => {
                collect_set_prototype_add_direct_function_ids_from_expr(expr, ids);
            }
            LoweredStmt::ModuleExportsUpdate { .. }
            | LoweredStmt::ForAwaitOfLower { .. }
            | LoweredStmt::Break { .. }
            | LoweredStmt::Continue { .. }
            | LoweredStmt::ClassDecl { .. } => {}
        }
    }
}

fn collect_set_prototype_add_direct_function_ids_from_expr(
    expr: &LoweredExpr,
    ids: &mut HashSet<FuncId>,
) {
    match expr {
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::SetPrototypeAddSet,
            args,
            ..
        } => {
            if let [LoweredExpr::Number(id, _)] = args.as_slice()
                && *id >= 0
            {
                ids.insert(FuncId(*id as usize));
            }
            for arg in args {
                collect_set_prototype_add_direct_function_ids_from_expr(arg, ids);
            }
        }
        LoweredExpr::RuntimeCall { args, .. } | LoweredExpr::Call { args, .. } => {
            for arg in args {
                collect_set_prototype_add_direct_function_ids_from_expr(arg, ids);
            }
        }
        LoweredExpr::Block { stmts, result, .. } => {
            collect_set_prototype_add_direct_function_ids_from_stmts(stmts, ids);
            collect_set_prototype_add_direct_function_ids_from_expr(result, ids);
        }
        LoweredExpr::Binary { left, right, .. } => {
            collect_set_prototype_add_direct_function_ids_from_expr(left, ids);
            collect_set_prototype_add_direct_function_ids_from_expr(right, ids);
        }
        LoweredExpr::Unary { expr, .. }
        | LoweredExpr::Assign { expr, .. }
        | LoweredExpr::LogicalAssign { expr, .. }
        | LoweredExpr::PromiseGetValue { promise: expr, .. }
        | LoweredExpr::EnvCellNew(expr, _)
        | LoweredExpr::EnvCellSet { expr, .. } => {
            collect_set_prototype_add_direct_function_ids_from_expr(expr, ids);
        }
        LoweredExpr::LogicalPropertyAssign { expr, .. } => {
            collect_set_prototype_add_direct_function_ids_from_expr(expr, ids);
        }
        LoweredExpr::PropertyGet { obj, .. } | LoweredExpr::OptionalPropertyGet { obj, .. } => {
            collect_set_prototype_add_direct_function_ids_from_expr(obj, ids);
        }
        LoweredExpr::PropertySet { object, value, .. } => {
            collect_set_prototype_add_direct_function_ids_from_expr(object, ids);
            collect_set_prototype_add_direct_function_ids_from_expr(value, ids);
        }
        LoweredExpr::PropertySetDynamic {
            object,
            index,
            value,
            ..
        } => {
            collect_set_prototype_add_direct_function_ids_from_expr(object, ids);
            collect_set_prototype_add_direct_function_ids_from_expr(index, ids);
            collect_set_prototype_add_direct_function_ids_from_expr(value, ids);
        }
        LoweredExpr::ArrayNew { elements, .. } => {
            for element in elements {
                collect_set_prototype_add_direct_function_ids_from_expr(element, ids);
            }
        }
        LoweredExpr::ObjectNew { props, .. } => {
            for (_, value) in props {
                collect_set_prototype_add_direct_function_ids_from_expr(value, ids);
            }
        }
        _ => {}
    }
}

fn static_analysis_ctx(static_locals: HashMap<LocalId, StaticValue>) -> FunctionCtx {
    FunctionCtx {
        locals: HashMap::new(),
        local_types: HashMap::new(),
        static_locals,
        value_reprs: NativeValueReprState::default(),
        raw_string_locals: HashSet::new(),
        static_arrays: HashMap::new(),
        static_objects: HashMap::new(),
        runtime_array_locals: HashSet::new(),
        array_copy_to_original: HashMap::new(),
        switch_value_local: 0,
        returns_value: false,
        module_id: None,
        controls: Vec::new(),
        gc_root_base_slot: None,
        gc_activation_roots: false,
        set_prototype_add: None,
        collection_iterator_locals: HashSet::new(),
        collection_identity_object_locals: HashSet::new(),
    }
}

fn static_array_slot(ctx: &FunctionCtx, obj: &LoweredExpr, key: &LoweredExpr) -> Option<usize> {
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let root = static_array_root(ctx, *local)?;
    let slots = ctx.static_arrays.get(&root)?;
    let LoweredExpr::Number(index, _) = key else {
        return None;
    };
    slots.get(*index as usize).copied()
}

fn static_array_repr_at(repr: Option<NativeArrayValueRepr>, index: i32) -> Option<NativeValueRepr> {
    match repr? {
        NativeArrayValueRepr::Homogeneous(repr) => Some(repr),
        NativeArrayValueRepr::Alternating { even, odd } => {
            if index.rem_euclid(2) == 0 {
                even
            } else {
                odd
            }
        }
    }
}

fn emit_static_array_slot_as_tagged(
    out: &mut Vec<WasmInstr>,
    slot: usize,
    repr: Option<NativeValueRepr>,
) {
    out.push(WasmInstr::LocalGet(slot));
    match repr {
        Some(NativeValueRepr::TaggedValue) => {}
        Some(NativeValueRepr::RawString) => {
            out.push(WasmInstr::I32Const(ValueTag::STRING_TAG as i32));
            out.push(WasmInstr::I32Or);
        }
        None => {
            out.push(WasmInstr::Call(
                RuntimeFn::NumberFromI32.symbol().to_owned(),
            ));
        }
    }
}

fn static_array_slot_with_functions(
    ctx: &FunctionCtx,
    obj: &LoweredExpr,
    key: &LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<usize> {
    if let Some(slot) = static_array_slot(ctx, obj, key) {
        return Some(slot);
    }
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    let root = static_array_root(ctx, *local)?;
    let slots = ctx.static_arrays.get(&root)?;
    let key = static_property_key_from_locals_with_functions(&ctx.static_locals, key, functions)?;
    let index = key.parse::<usize>().ok()?;
    if key != index.to_string() {
        return None;
    }
    slots.get(index).copied()
}

fn static_array_root(ctx: &FunctionCtx, local: LocalId) -> Option<LocalId> {
    if ctx.static_arrays.contains_key(&local) {
        return Some(local);
    }
    let StaticValue::Array(elements) = ctx.static_locals.get(&local)? else {
        return None;
    };
    let mut matches = ctx.static_arrays.iter().filter_map(|(candidate, slots)| {
        if slots.len() != elements.len() {
            return None;
        }
        match ctx.static_locals.get(candidate) {
            Some(StaticValue::Array(candidate_elements)) if candidate_elements == elements => {
                Some(*candidate)
            }
            _ => None,
        }
    });
    let root = matches.next()?;
    matches.next().is_none().then_some(root)
}

fn static_array_len(ctx: &FunctionCtx, expr: &LoweredExpr) -> Option<usize> {
    let LoweredExpr::Local(local, _) = expr else {
        return None;
    };
    if let Some(StaticValue::Array(elements)) = ctx.static_locals.get(local) {
        return Some(elements.len());
    }
    ctx.static_arrays.get(local).map(Vec::len)
}

fn static_array_len_with_functions(
    ctx: &FunctionCtx,
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
) -> Option<usize> {
    static_array_len(ctx, expr)
        .or_else(|| static_array_len_from_expr_with_functions(expr, &ctx.static_locals, functions))
}

fn collection_iterator_expr(ctx: &FunctionCtx, expr: &LoweredExpr) -> Option<LocalId> {
    let LoweredExpr::Local(local, _) = expr else {
        return None;
    };
    ctx.collection_iterator_locals
        .contains(local)
        .then_some(*local)
}

fn collection_iterator_property_access_is_undefined(
    ctx: &FunctionCtx,
    obj: &LoweredExpr,
    key: &str,
) -> bool {
    collection_iterator_expr(ctx, obj).is_some()
        && (key == "length" || canonical_static_array_index(key).is_some())
}

fn static_object_slot(ctx: &FunctionCtx, obj: &LoweredExpr, key: &str) -> Option<usize> {
    let LoweredExpr::Local(local, _) = obj else {
        return None;
    };
    ctx.static_objects.get(local)?.get(key).copied()
}

fn static_object_dynamic_slot(
    ctx: &FunctionCtx,
    obj: &LoweredExpr,
    key: &LoweredExpr,
) -> Option<usize> {
    let key = static_property_key_from_locals(&ctx.static_locals, key)?;
    static_object_slot(ctx, obj, &key)
}

fn module_export_global(ctx: &FunctionCtx, name: &str) -> Result<String, Diagnostic> {
    let module_id = ctx.module_id.ok_or_else(|| {
        unsupported("native LoweredProgram emitter cannot export outside module initializer")
    })?;
    Ok(module_export_global_symbol(module_id, name))
}

fn binary_op_instr(op: LoweredBinaryOp) -> Result<WasmInstr, Diagnostic> {
    match op {
        LoweredBinaryOp::Add => Ok(WasmInstr::I32Add),
        LoweredBinaryOp::Subtract => Ok(WasmInstr::I32Sub),
        LoweredBinaryOp::Multiply => Ok(WasmInstr::I32Mul),
        LoweredBinaryOp::Divide => Ok(WasmInstr::I32DivS),
        LoweredBinaryOp::Modulo => Ok(WasmInstr::I32RemS),
        LoweredBinaryOp::BitwiseAnd => Ok(WasmInstr::I32And),
        LoweredBinaryOp::BitwiseOr => Ok(WasmInstr::I32Or),
        LoweredBinaryOp::BitwiseXor => Ok(WasmInstr::I32Xor),
        LoweredBinaryOp::Less => Ok(WasmInstr::I32LtS),
        LoweredBinaryOp::LessEqual => Ok(WasmInstr::I32LeS),
        LoweredBinaryOp::Greater => Ok(WasmInstr::I32GtS),
        LoweredBinaryOp::GreaterEqual => Ok(WasmInstr::I32GeS),
        LoweredBinaryOp::StrictEqual | LoweredBinaryOp::EqualEqual => Ok(WasmInstr::I32Eq),
        LoweredBinaryOp::StrictNotEqual | LoweredBinaryOp::BangEqual => Ok(WasmInstr::I32Ne),
        LoweredBinaryOp::Shl => Ok(WasmInstr::I32Shl),
        LoweredBinaryOp::Shr => Ok(WasmInstr::I32ShrS),
        LoweredBinaryOp::ShrU => Ok(WasmInstr::I32ShrU),
        LoweredBinaryOp::Power => Err(unsupported(
            "native LoweredProgram emitter does not support the ** operator as a raw wasm binary op",
        )),
        LoweredBinaryOp::And => Err(unsupported(
            "native LoweredProgram emitter does not support the && operator as a raw wasm binary op",
        )),
        LoweredBinaryOp::Or => Err(unsupported(
            "native LoweredProgram emitter does not support the || operator as a raw wasm binary op",
        )),
        LoweredBinaryOp::NullishCoalesce => Err(unsupported(
            "native LoweredProgram emitter does not support the ?? operator as a raw wasm binary op",
        )),
    }
}

fn native_numeric_binary_runtime_fn(op: LoweredBinaryOp) -> Option<RuntimeFn> {
    match op {
        LoweredBinaryOp::Add => Some(RuntimeFn::Add),
        LoweredBinaryOp::Subtract => Some(RuntimeFn::Sub),
        LoweredBinaryOp::Multiply => Some(RuntimeFn::Mul),
        LoweredBinaryOp::Divide => Some(RuntimeFn::Div),
        LoweredBinaryOp::Modulo => Some(RuntimeFn::Mod),
        LoweredBinaryOp::Power => Some(RuntimeFn::MathPow),
        _ => None,
    }
}

fn strip_relational_number_coerce_for_known_bigint<'a>(
    left: &'a LoweredExpr,
    right: &'a LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
) -> (&'a LoweredExpr, &'a LoweredExpr) {
    let left_inner = strip_unary_plus(left);
    let right_inner = strip_unary_plus(right);
    if lowered_expr_is_static_bigint(left_inner, ctx, functions)
        || lowered_expr_is_static_bigint(right_inner, ctx, functions)
    {
        (left_inner, right_inner)
    } else {
        (left, right)
    }
}

fn strip_unary_plus(expr: &LoweredExpr) -> &LoweredExpr {
    match expr {
        LoweredExpr::Unary {
            op: LoweredUnaryOp::Plus,
            expr,
            ..
        } => expr.as_ref(),
        _ => expr,
    }
}

fn lowered_expr_is_static_bigint(
    expr: &LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
) -> bool {
    if let LoweredExpr::Block { stmts, result, .. } = expr {
        let mut nested_locals = ctx.static_locals.clone();
        collect_static_locals_with_functions(stmts, &mut nested_locals, functions);
        return matches!(
            static_value_from_expr_with_functions(result, &nested_locals, functions),
            Some(StaticValue::Primitive(LoweredExpr::BigIntLiteral { .. }))
        );
    }
    matches!(
        static_value_from_expr_with_functions(expr, &ctx.static_locals, functions),
        Some(StaticValue::Primitive(LoweredExpr::BigIntLiteral { .. }))
    )
}

fn native_bitwise_runtime_fn(op: LoweredBinaryOp) -> Option<RuntimeFn> {
    match op {
        LoweredBinaryOp::BitwiseAnd => Some(RuntimeFn::BitwiseAnd),
        LoweredBinaryOp::BitwiseXor => Some(RuntimeFn::BitwiseXor),
        LoweredBinaryOp::BitwiseOr => Some(RuntimeFn::BitwiseOr),
        _ => None,
    }
}

fn native_equality_runtime_fn(op: LoweredBinaryOp) -> Option<(RuntimeFn, bool)> {
    match op {
        LoweredBinaryOp::StrictEqual => Some((RuntimeFn::StrictEqual, false)),
        LoweredBinaryOp::EqualEqual => Some((RuntimeFn::EqualEqual, false)),
        LoweredBinaryOp::StrictNotEqual => Some((RuntimeFn::StrictEqual, true)),
        LoweredBinaryOp::BangEqual => Some((RuntimeFn::EqualEqual, true)),
        _ => None,
    }
}

fn native_nullish_equality_result(
    op: LoweredBinaryOp,
    left: &LoweredExpr,
    right: &LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
) -> Option<bool> {
    let negate = matches!(
        op,
        LoweredBinaryOp::StrictNotEqual | LoweredBinaryOp::BangEqual
    );
    if native_expr_is_nullish(left, ctx, functions)
        && native_expr_definitely_non_nullish(right, ctx, functions)
    {
        return Some(negate);
    }
    if native_expr_is_nullish(right, ctx, functions)
        && native_expr_definitely_non_nullish(left, ctx, functions)
    {
        return Some(negate);
    }
    None
}

fn native_expr_is_nullish(
    expr: &LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
) -> bool {
    static_value_from_expr_with_functions(expr, &ctx.static_locals, functions)
        .as_ref()
        .is_some_and(static_value_is_nullish)
}

fn native_expr_definitely_non_nullish(
    expr: &LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
) -> bool {
    if let Some(value) = static_value_from_expr_with_functions(expr, &ctx.static_locals, functions)
    {
        return !static_value_is_nullish(&value);
    }
    matches!(
        expr,
        LoweredExpr::ArrayNew { .. }
            | LoweredExpr::ArrayNewSparse { .. }
            | LoweredExpr::ObjectNew { .. }
            | LoweredExpr::ErrorNew { .. }
            | LoweredExpr::ArrowFn { .. }
            | LoweredExpr::ClassPrototype(_, _)
    ) || matches!(expr, LoweredExpr::Local(local, _) if native_local_definitely_non_nullish(*local, ctx))
}

fn native_local_definitely_non_nullish(local: LocalId, ctx: &FunctionCtx) -> bool {
    ctx.runtime_array_locals.contains(&local)
        || ctx.static_arrays.contains_key(&local)
        || ctx.static_objects.contains_key(&local)
        || ctx.value_reprs.arrays.contains_key(&local)
        || ctx.value_reprs.maps.contains_key(&local)
        || ctx.value_reprs.sets.contains_key(&local)
}

fn native_relational_runtime_fn(op: LoweredBinaryOp) -> Option<RuntimeFn> {
    match op {
        LoweredBinaryOp::Less => Some(RuntimeFn::Less),
        LoweredBinaryOp::LessEqual => Some(RuntimeFn::LessEqual),
        LoweredBinaryOp::Greater => Some(RuntimeFn::Greater),
        LoweredBinaryOp::GreaterEqual => Some(RuntimeFn::GreaterEqual),
        _ => None,
    }
}

fn native_static_primitive_can_emit_tagged(expr: &LoweredExpr) -> bool {
    matches!(
        expr,
        LoweredExpr::Number(_, _)
            | LoweredExpr::String(_, _)
            | LoweredExpr::Bool(_, _)
            | LoweredExpr::Null(_)
            | LoweredExpr::Undefined(_)
    )
}

fn native_raw_number_operand(expr: &LoweredExpr, functions: &[LoweredFunction]) -> bool {
    match expr {
        LoweredExpr::Number(_, _) | LoweredExpr::Local(_, _) => true,
        LoweredExpr::Call {
            kind: FunctionCallKind::User(func_id),
            ..
        } => user_function_return_type(functions, *func_id) == InferredType::Number,
        LoweredExpr::Binary {
            left, op, right, ..
        } if native_numeric_binary_runtime_fn(*op).is_some() => {
            native_raw_number_operand(left, functions)
                && native_raw_number_operand(right, functions)
        }
        _ => false,
    }
}

fn native_expr_unsupported_reason(expr: &LoweredExpr) -> &'static str {
    match expr {
        LoweredExpr::ArrowFn {
            representation: ClosureRepresentation::HeapObject,
            ..
        } => "native LoweredProgram emitter does not support heap closure expressions",
        LoweredExpr::ArrowFn { .. } => {
            "native LoweredProgram emitter does not support this closure expression"
        }
        LoweredExpr::Number(_, _)
        | LoweredExpr::DecimalNumber(_, _)
        | LoweredExpr::BigIntLiteral { .. }
        | LoweredExpr::String(_, _)
        | LoweredExpr::Bool(_, _)
        | LoweredExpr::Null(_)
        | LoweredExpr::Undefined(_)
        | LoweredExpr::Local(_, _)
        | LoweredExpr::EnvCellNew(_, _)
        | LoweredExpr::EnvCellGet(_, _)
        | LoweredExpr::EnvCellSet { .. }
        | LoweredExpr::Unary { .. }
        | LoweredExpr::Binary { .. }
        | LoweredExpr::PropertyIn { .. }
        | LoweredExpr::PropertyInDynamic { .. }
        | LoweredExpr::Call { .. }
        | LoweredExpr::Assign { .. }
        | LoweredExpr::LogicalAssign { .. }
        | LoweredExpr::LogicalPropertyAssign { .. }
        | LoweredExpr::LogicalComputedPropertyAssign { .. }
        | LoweredExpr::LogicalComputedMemberAssign { .. }
        | LoweredExpr::LogicalMemberAssign { .. }
        | LoweredExpr::ArrayNew { .. }
        | LoweredExpr::ArrayNewSparse { .. }
        | LoweredExpr::ArrayGet { .. }
        | LoweredExpr::Index { .. }
        | LoweredExpr::GetLength(_, _)
        | LoweredExpr::ObjectNew { .. }
        | LoweredExpr::ErrorNew { .. }
        | LoweredExpr::PropertyGet { .. }
        | LoweredExpr::OptionalPropertyGet { .. }
        | LoweredExpr::PropertyGetDynamic { .. }
        | LoweredExpr::OptionalIndex { .. }
        | LoweredExpr::OptionalCall { .. }
        | LoweredExpr::MethodCall { .. }
        | LoweredExpr::PromiseGetValue { .. }
        | LoweredExpr::RuntimeCall { .. }
        | LoweredExpr::PropertySet { .. }
        | LoweredExpr::PropertyDelete { .. }
        | LoweredExpr::PropertyDeleteDynamic { .. }
        | LoweredExpr::PropertySetDynamic { .. }
        | LoweredExpr::New { .. }
        | LoweredExpr::ClassPrototype(_, _)
        | LoweredExpr::BuiltinErrorPrototype(_, _)
        | LoweredExpr::ModuleLoad { .. }
        | LoweredExpr::Block { .. } => {
            "native LoweredProgram emitter does not support this expression variant"
        }
        LoweredExpr::This(_) => "native LoweredProgram emitter does not support this binding",
    }
}

fn static_typeof_bytes(expr: &LoweredExpr) -> Option<&'static [u8]> {
    match expr {
        LoweredExpr::Number(value, _)
            if *value == ValueTag::BUILTIN_PARSE_INT_VALUE
                || *value == ValueTag::BUILTIN_PARSE_FLOAT_VALUE =>
        {
            Some(b"function")
        }
        LoweredExpr::Number(_, _) | LoweredExpr::DecimalNumber(_, _) => Some(b"number"),
        LoweredExpr::BigIntLiteral { .. } => Some(b"bigint"),
        LoweredExpr::String(value, _) if static_regexp_literal_parts(value).is_some() => {
            Some(b"object")
        }
        LoweredExpr::String(_, _) => Some(b"string"),
        LoweredExpr::Bool(_, _) => Some(b"boolean"),
        LoweredExpr::Undefined(_) => Some(b"undefined"),
        LoweredExpr::Null(_) => Some(b"object"),
        _ => None,
    }
}

fn native_typeof_bytes(expr: &LoweredExpr, ctx: &FunctionCtx) -> Option<&'static [u8]> {
    if let Some(bytes) = static_typeof_bytes(expr) {
        return Some(bytes);
    }
    match expr {
        LoweredExpr::Local(local, _) | LoweredExpr::EnvCellGet(local, _) => {
            if let Some(value) = ctx.static_locals.get(local) {
                match value {
                    StaticValue::Primitive(value) => {
                        if let Some(bytes) = static_typeof_bytes(value) {
                            return Some(bytes);
                        }
                    }
                    StaticValue::Closure { .. } | StaticValue::ArrayPushManyClosure => {
                        return Some(b"function");
                    }
                    StaticValue::Object(_)
                    | StaticValue::ObjectAlias(_)
                    | StaticValue::Array(_)
                    | StaticValue::SparseArray(_)
                    | StaticValue::ArrayIterator { .. }
                    | StaticValue::Generator { .. }
                    | StaticValue::ArrayBuffer(_)
                    | StaticValue::DataView { .. }
                    | StaticValue::DateObject(_) => return Some(b"object"),
                    StaticValue::Symbol(_) => return Some(b"symbol"),
                    StaticValue::TaggedString => return Some(b"string"),
                    StaticValue::TaggedNumber => return Some(b"number"),
                    StaticValue::TaggedRuntimeValue => {}
                }
            }
            match ctx
                .local_types
                .get(local)
                .copied()
                .unwrap_or(InferredType::Unknown)
            {
                InferredType::Number => Some(b"number"),
                InferredType::String => Some(b"string"),
                InferredType::Boolean => Some(b"boolean"),
                InferredType::Unknown => None,
            }
        }
        LoweredExpr::ArrowFn { .. } => Some(b"function"),
        LoweredExpr::ObjectNew { .. }
        | LoweredExpr::ArrayNew { .. }
        | LoweredExpr::ArrayNewSparse { .. }
        | LoweredExpr::ErrorNew { .. }
        | LoweredExpr::ClassPrototype(_, _) => Some(b"object"),
        LoweredExpr::BuiltinErrorPrototype(_, _) => Some(b"function"),
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::SymbolWellKnown,
            ..
        } => Some(b"symbol"),
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::GlobalThis,
            args,
            ..
        } if args.is_empty() => Some(b"object"),
        LoweredExpr::RuntimeCall {
            intrinsic:
                RuntimeFn::TruthyBool
                | RuntimeFn::Not
                | RuntimeFn::And
                | RuntimeFn::Or
                | RuntimeFn::InstanceOf,
            ..
        }
        | LoweredExpr::Binary {
            op:
                LoweredBinaryOp::StrictEqual
                | LoweredBinaryOp::EqualEqual
                | LoweredBinaryOp::StrictNotEqual
                | LoweredBinaryOp::BangEqual
                | LoweredBinaryOp::Less
                | LoweredBinaryOp::LessEqual
                | LoweredBinaryOp::Greater
                | LoweredBinaryOp::GreaterEqual,
            ..
        }
        | LoweredExpr::Unary {
            op: LoweredUnaryOp::Not | LoweredUnaryOp::Delete,
            ..
        } => Some(b"boolean"),
        LoweredExpr::Unary {
            op: LoweredUnaryOp::TypeOf,
            ..
        }
        | LoweredExpr::RuntimeCall {
            intrinsic:
                RuntimeFn::SymbolDescription
                | RuntimeFn::SymbolToString
                | RuntimeFn::Concat
                | RuntimeFn::ErrorMessage,
            ..
        } => Some(b"string"),
        LoweredExpr::GetLength(_, _)
        | LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::ArrayPushMany,
            ..
        }
        | LoweredExpr::Call {
            kind: FunctionCallKind::Builtin(BuiltinId::MathPow),
            ..
        }
        | LoweredExpr::Binary {
            op:
                LoweredBinaryOp::Add
                | LoweredBinaryOp::Subtract
                | LoweredBinaryOp::Multiply
                | LoweredBinaryOp::Power
                | LoweredBinaryOp::Divide
                | LoweredBinaryOp::Modulo
                | LoweredBinaryOp::BitwiseAnd
                | LoweredBinaryOp::BitwiseXor
                | LoweredBinaryOp::BitwiseOr,
            ..
        }
        | LoweredExpr::Unary {
            op: LoweredUnaryOp::Plus | LoweredUnaryOp::Negate,
            ..
        } => Some(b"number"),
        _ => None,
    }
}

fn local_index(ctx: &FunctionCtx, local: LocalId) -> Result<usize, Diagnostic> {
    ctx.locals.get(&local).copied().ok_or_else(|| Diagnostic {
        code: DiagCode::InvariantViolation,
        message: format!("native LoweredProgram emitter missing local {:?}", local),
        span: None,
        phase: None,
    })
}

fn native_gc_root_table_initializer(root_count: usize, call_frame_roots: bool) -> Vec<WasmInstr> {
    if root_count == 0 && !call_frame_roots {
        return Vec::new();
    }
    let static_root_bytes = root_count * std::mem::size_of::<u32>();
    let call_frame_root_bytes = if call_frame_roots {
        Layout::GC_CALL_FRAME_ROOT_STACK_BYTES as usize
    } else {
        0
    };
    let root_bytes = static_root_bytes + call_frame_root_bytes;
    let mut out = vec![
        WasmInstr::I32Const(root_count as i32),
        WasmInstr::GlobalSet("$gc_root_count".to_owned()),
        WasmInstr::I32Const(root_bytes as i32),
        WasmInstr::Call(RuntimeFn::AllocHeap.symbol().to_owned()),
        WasmInstr::GlobalSet("$gc_root_base".to_owned()),
    ];
    if call_frame_roots {
        out.extend([
            WasmInstr::GlobalGet("$gc_root_base".to_owned()),
            WasmInstr::I32Const(static_root_bytes as i32),
            WasmInstr::I32Add,
            WasmInstr::GlobalSet("$gc_call_frame_base".to_owned()),
            WasmInstr::GlobalGet("$gc_call_frame_base".to_owned()),
            WasmInstr::GlobalSet("$gc_call_frame_top".to_owned()),
            WasmInstr::GlobalGet("$gc_call_frame_base".to_owned()),
            WasmInstr::I32Const(call_frame_root_bytes as i32),
            WasmInstr::I32Add,
            WasmInstr::GlobalSet("$gc_call_frame_limit".to_owned()),
            WasmInstr::I32Const(0),
            WasmInstr::GlobalSet("$gc_call_frame_current".to_owned()),
        ]);
    }
    out
}

fn native_gc_activation_frame_push(enabled: bool, local_count: usize) -> Vec<WasmInstr> {
    if !enabled {
        return Vec::new();
    }
    let frame_bytes =
        Layout::GC_CALL_FRAME_HEADER_SIZE as usize + local_count * std::mem::size_of::<u32>();
    let mut out = vec![
        WasmInstr::GlobalGet("$gc_call_frame_top".to_owned()),
        WasmInstr::I32Const(frame_bytes as i32),
        WasmInstr::I32Add,
        WasmInstr::GlobalGet("$gc_call_frame_limit".to_owned()),
        WasmInstr::I32GtU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::Unreachable,
        WasmInstr::End,
        WasmInstr::GlobalGet("$gc_call_frame_top".to_owned()),
        WasmInstr::GlobalGet("$gc_call_frame_current".to_owned()),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::GlobalGet("$gc_call_frame_top".to_owned()),
        WasmInstr::I32Const(local_count as i32),
        WasmInstr::I32Store {
            align: 2,
            offset: 4,
        },
        WasmInstr::GlobalGet("$gc_call_frame_top".to_owned()),
        WasmInstr::GlobalSet("$gc_call_frame_current".to_owned()),
        WasmInstr::GlobalGet("$gc_call_frame_top".to_owned()),
        WasmInstr::I32Const(frame_bytes as i32),
        WasmInstr::I32Add,
        WasmInstr::GlobalSet("$gc_call_frame_top".to_owned()),
    ];
    for local_index in 0..local_count {
        emit_gc_activation_root_mirror_index(&mut out, local_index);
    }
    out
}

fn native_gc_activation_frame_pop(out: &mut Vec<WasmInstr>, ctx: &FunctionCtx) {
    if !ctx.gc_activation_roots {
        return;
    }
    out.extend([
        WasmInstr::GlobalGet("$gc_call_frame_current".to_owned()),
        WasmInstr::GlobalSet("$gc_call_frame_top".to_owned()),
        WasmInstr::GlobalGet("$gc_call_frame_current".to_owned()),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::GlobalSet("$gc_call_frame_current".to_owned()),
    ]);
}

fn local_set_with_gc_mirror(out: &mut Vec<WasmInstr>, ctx: &FunctionCtx, local_index: usize) {
    out.push(WasmInstr::LocalSet(local_index));
    emit_gc_root_mirror_index(out, ctx, local_index);
}

fn local_tee_with_gc_mirror(out: &mut Vec<WasmInstr>, ctx: &FunctionCtx, local_index: usize) {
    out.push(WasmInstr::LocalTee(local_index));
    emit_gc_root_mirror_index(out, ctx, local_index);
}

fn emit_gc_root_mirror_index(out: &mut Vec<WasmInstr>, ctx: &FunctionCtx, local_index: usize) {
    if ctx.gc_activation_roots {
        emit_gc_activation_root_mirror_index(out, local_index);
        return;
    }
    let Some(base_slot) = ctx.gc_root_base_slot else {
        return;
    };
    let slot = base_slot + local_index;
    let offset = slot * std::mem::size_of::<u32>();
    out.extend([
        WasmInstr::GlobalGet("$gc_root_base".to_owned()),
        WasmInstr::I32Const(offset as i32),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(local_index),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
    ]);
}

fn emit_gc_activation_root_mirror_index(out: &mut Vec<WasmInstr>, local_index: usize) {
    let offset =
        Layout::GC_CALL_FRAME_HEADER_SIZE as usize + local_index * std::mem::size_of::<u32>();
    out.extend([
        WasmInstr::GlobalGet("$gc_call_frame_current".to_owned()),
        WasmInstr::I32Const(offset as i32),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(local_index),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
    ]);
}

fn native_stmts_need_exception_path(
    stmts: &[LoweredStmt],
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
    function_results: &HashMap<FuncId, bool>,
) -> bool {
    stmts
        .iter()
        .any(|stmt| native_stmt_need_exception_path(stmt, ctx, functions, function_results))
}

fn native_stmts_can_catch_with_exception_pending(
    stmts: &[LoweredStmt],
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    stmts
        .iter()
        .all(|stmt| native_stmt_can_catch_with_exception_pending(stmt, functions, visiting))
}

fn native_stmt_can_catch_with_exception_pending(
    stmt: &LoweredStmt,
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    match stmt {
        LoweredStmt::Let(_, expr, _)
        | LoweredStmt::Assign(_, expr, _)
        | LoweredStmt::Expr(expr, _)
        | LoweredStmt::Yield(expr, _)
        | LoweredStmt::Export { expr, .. }
        | LoweredStmt::ModuleExportsAssign { expr, .. } => {
            native_expr_can_run_in_catchable_try(expr, functions, visiting)
        }
        LoweredStmt::Return(expr, _) => {
            native_expr_can_run_in_catchable_try(expr, functions, visiting)
        }
        LoweredStmt::Throw(_, _) => true,
        LoweredStmt::Block(stmts, _) => {
            native_stmts_can_catch_with_exception_pending(stmts, functions, visiting)
        }
        LoweredStmt::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            native_expr_can_run_in_catchable_try(condition, functions, visiting)
                && native_stmts_can_catch_with_exception_pending(then_body, functions, visiting)
                && native_stmts_can_catch_with_exception_pending(else_body, functions, visiting)
        }
        _ => false,
    }
}

fn native_expr_can_run_in_catchable_try(
    expr: &LoweredExpr,
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    match expr {
        LoweredExpr::Number(_, _)
        | LoweredExpr::DecimalNumber(_, _)
        | LoweredExpr::BigIntLiteral { .. }
        | LoweredExpr::String(_, _)
        | LoweredExpr::Bool(_, _)
        | LoweredExpr::Null(_)
        | LoweredExpr::Undefined(_)
        | LoweredExpr::Local(_, _)
        | LoweredExpr::ClassPrototype(_, _)
        | LoweredExpr::BuiltinErrorPrototype(_, _)
        | LoweredExpr::ModuleLoad { .. }
        | LoweredExpr::ArrowFn { .. }
        | LoweredExpr::This(_) => true,
        LoweredExpr::EnvCellNew(inner, _)
        | LoweredExpr::EnvCellSet { expr: inner, .. }
        | LoweredExpr::Unary { expr: inner, .. }
        | LoweredExpr::Assign { expr: inner, .. }
        | LoweredExpr::LogicalAssign { expr: inner, .. }
        | LoweredExpr::PromiseGetValue { promise: inner, .. }
        | LoweredExpr::GetLength(inner, _) => {
            native_expr_can_run_in_catchable_try(inner, functions, visiting)
        }
        LoweredExpr::EnvCellGet(_, _) => true,
        LoweredExpr::Binary { left, right, .. } => {
            native_expr_can_run_in_catchable_try(left, functions, visiting)
                && native_expr_can_run_in_catchable_try(right, functions, visiting)
        }
        LoweredExpr::ArrayNew { elements, .. } => elements
            .iter()
            .all(|expr| native_expr_can_run_in_catchable_try(expr, functions, visiting)),
        LoweredExpr::ArrayNewSparse { slots, .. } => slots.iter().all(|slot| match slot {
            ts2wasm_ir::lowered::LoweredArraySlot::Present(expr) => {
                native_expr_can_run_in_catchable_try(expr, functions, visiting)
            }
            ts2wasm_ir::lowered::LoweredArraySlot::Hole => true,
        }),
        LoweredExpr::ObjectNew { props, .. } => props
            .iter()
            .all(|(_, expr)| native_expr_can_run_in_catchable_try(expr, functions, visiting)),
        LoweredExpr::ErrorNew {
            message,
            cause,
            errors,
            ..
        } => {
            native_expr_can_run_in_catchable_try(message, functions, visiting)
                && cause.as_deref().is_none_or(|expr| {
                    native_expr_can_run_in_catchable_try(expr, functions, visiting)
                })
                && errors.as_deref().is_none_or(|expr| {
                    native_expr_can_run_in_catchable_try(expr, functions, visiting)
                })
        }
        LoweredExpr::Block { stmts, result, .. } => {
            native_stmts_can_catch_with_exception_pending(stmts, functions, visiting)
                && native_expr_can_run_in_catchable_try(result, functions, visiting)
        }
        LoweredExpr::Call { kind, args, .. } => match kind {
            FunctionCallKind::Builtin(BuiltinId::ConsoleLog | BuiltinId::MathPow) => args
                .iter()
                .all(|arg| native_expr_can_run_in_catchable_try(arg, functions, visiting)),
            FunctionCallKind::User(func_id) => {
                args.iter()
                    .all(|arg| native_expr_can_run_in_catchable_try(arg, functions, visiting))
                    && native_user_function_can_run_in_catchable_try(*func_id, functions, visiting)
            }
            FunctionCallKind::Builtin(_) => false,
        },
        LoweredExpr::PropertyGet { obj, .. } | LoweredExpr::OptionalPropertyGet { obj, .. } => {
            native_expr_can_run_in_catchable_try(obj, functions, visiting)
        }
        LoweredExpr::PropertyDelete { object, .. } => {
            native_expr_can_run_in_catchable_try(object, functions, visiting)
        }
        LoweredExpr::PropertyGetDynamic { obj, key, .. }
        | LoweredExpr::OptionalIndex {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::Index {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::ArrayGet {
            arr: obj,
            index: key,
            ..
        }
        | LoweredExpr::PropertyDeleteDynamic {
            object: obj, key, ..
        } => {
            native_expr_can_run_in_catchable_try(obj, functions, visiting)
                && native_expr_can_run_in_catchable_try(key, functions, visiting)
        }
        LoweredExpr::PropertySet { object, value, .. } => {
            native_expr_can_run_in_catchable_try(object, functions, visiting)
                && native_expr_can_run_in_catchable_try(value, functions, visiting)
        }
        LoweredExpr::PropertySetDynamic {
            object,
            index,
            value,
            ..
        } => {
            native_expr_can_run_in_catchable_try(object, functions, visiting)
                && native_expr_can_run_in_catchable_try(index, functions, visiting)
                && native_expr_can_run_in_catchable_try(value, functions, visiting)
        }
        expr => native_expr_can_raise_exception_pending(expr),
    }
}

fn native_user_function_can_run_in_catchable_try(
    func_id: FuncId,
    functions: &[LoweredFunction],
    visiting: &mut HashSet<FuncId>,
) -> bool {
    if !visiting.insert(func_id) {
        return false;
    }
    let result = functions
        .iter()
        .find(|function| function.id == func_id)
        .is_some_and(|function| {
            native_stmts_can_catch_with_exception_pending(&function.body, functions, visiting)
        });
    visiting.remove(&func_id);
    result
}

fn native_expr_can_raise_exception_pending(expr: &LoweredExpr) -> bool {
    matches!(
        expr,
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::BigIntMixedArithmeticTypeError
                | RuntimeFn::BigIntDivisionByZeroRangeError
                | RuntimeFn::BigIntDiv
                | RuntimeFn::BigIntRem,
            ..
        }
    ) || matches!(
        expr,
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::HeapClosureCall,
            args,
            ..
        } if !args.is_empty() && args.len() <= 9
    ) || matches!(
        expr,
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::ReflectConstruct,
            args,
            ..
        } if args.len() == 3
    ) || matches!(
        expr,
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::PrivateBrandCheck,
            args,
            ..
        } if args.len() == 2
    ) || matches!(
        expr,
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::PrivateFieldGet,
            args,
            ..
        } if args.len() == 3
    )
}

fn native_stmt_need_exception_path(
    stmt: &LoweredStmt,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
    function_results: &HashMap<FuncId, bool>,
) -> bool {
    match stmt {
        LoweredStmt::Block(stmts, _) => {
            native_stmts_need_exception_path(stmts, ctx, functions, function_results)
        }
        LoweredStmt::Let(_, expr, _)
        | LoweredStmt::Assign(_, expr, _)
        | LoweredStmt::Expr(expr, _)
        | LoweredStmt::Yield(expr, _)
        | LoweredStmt::Export { expr, .. }
        | LoweredStmt::ModuleExportsAssign { expr, .. } => {
            native_expr_may_throw(expr, ctx, functions, function_results)
        }
        LoweredStmt::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            native_expr_may_throw(condition, ctx, functions, function_results)
                || native_stmts_need_exception_path(then_body, ctx, functions, function_results)
                || native_stmts_need_exception_path(else_body, ctx, functions, function_results)
        }
        LoweredStmt::Return(_, _) => true,
        LoweredStmt::Throw(_, _)
        | LoweredStmt::TryFinally { .. }
        | LoweredStmt::TryCatch { .. }
        | LoweredStmt::Break { .. }
        | LoweredStmt::Continue { .. }
        | LoweredStmt::Switch { .. }
        | LoweredStmt::While { .. }
        | LoweredStmt::DoWhile { .. }
        | LoweredStmt::For { .. }
        | LoweredStmt::ForOf { .. }
        | LoweredStmt::ForAwaitOfLower { .. }
        | LoweredStmt::Labeled { .. } => true,
        LoweredStmt::ForIn { iter, .. } => {
            native_expr_may_throw(iter, ctx, functions, function_results)
        }
        LoweredStmt::ModuleExportsUpdate { .. } | LoweredStmt::ClassDecl { .. } => false,
    }
}

fn native_expr_may_throw(
    expr: &LoweredExpr,
    ctx: &FunctionCtx,
    functions: &[LoweredFunction],
    function_results: &HashMap<FuncId, bool>,
) -> bool {
    match expr {
        LoweredExpr::Number(_, _)
        | LoweredExpr::DecimalNumber(_, _)
        | LoweredExpr::BigIntLiteral { .. }
        | LoweredExpr::String(_, _)
        | LoweredExpr::Bool(_, _)
        | LoweredExpr::Null(_)
        | LoweredExpr::Undefined(_)
        | LoweredExpr::Local(_, _)
        | LoweredExpr::ClassPrototype(_, _)
        | LoweredExpr::BuiltinErrorPrototype(_, _)
        | LoweredExpr::ModuleLoad { .. }
        | LoweredExpr::ArrowFn { .. }
        | LoweredExpr::This(_) => false,
        LoweredExpr::EnvCellNew(inner, _) | LoweredExpr::PromiseGetValue { promise: inner, .. } => {
            native_expr_may_throw(inner, ctx, functions, function_results)
        }
        LoweredExpr::EnvCellGet(_, _) => false,
        LoweredExpr::EnvCellSet { expr, .. }
        | LoweredExpr::Unary { expr, .. }
        | LoweredExpr::Assign { expr, .. }
        | LoweredExpr::LogicalAssign { expr, .. } => {
            native_expr_may_throw(expr, ctx, functions, function_results)
        }
        LoweredExpr::Binary { left, right, .. } => {
            native_expr_may_throw(left, ctx, functions, function_results)
                || native_expr_may_throw(right, ctx, functions, function_results)
        }
        LoweredExpr::ArrayNew { elements, .. } => elements
            .iter()
            .any(|expr| native_expr_may_throw(expr, ctx, functions, function_results)),
        LoweredExpr::ArrayNewSparse { slots, .. } => slots.iter().any(|slot| match slot {
            ts2wasm_ir::lowered::LoweredArraySlot::Present(expr) => {
                native_expr_may_throw(expr, ctx, functions, function_results)
            }
            ts2wasm_ir::lowered::LoweredArraySlot::Hole => false,
        }),
        LoweredExpr::ObjectNew { props, .. } => props
            .iter()
            .any(|(_, expr)| native_expr_may_throw(expr, ctx, functions, function_results)),
        LoweredExpr::ErrorNew {
            message,
            cause,
            errors,
            ..
        } => {
            native_expr_may_throw(message, ctx, functions, function_results)
                || cause.as_deref().is_some_and(|expr| {
                    native_expr_may_throw(expr, ctx, functions, function_results)
                })
                || errors.as_deref().is_some_and(|expr| {
                    native_expr_may_throw(expr, ctx, functions, function_results)
                })
        }
        LoweredExpr::Block { stmts, result, .. } => {
            native_stmts_need_exception_path(stmts, ctx, functions, function_results)
                || native_expr_may_throw(result, ctx, functions, function_results)
        }
        LoweredExpr::Call { kind, args, .. } => match kind {
            FunctionCallKind::Builtin(BuiltinId::ConsoleLog | BuiltinId::MathPow) => args
                .iter()
                .any(|arg| native_expr_may_throw(arg, ctx, functions, function_results)),
            FunctionCallKind::Builtin(_) | FunctionCallKind::User(_) => true,
        },
        LoweredExpr::RuntimeCall {
            intrinsic: RuntimeFn::ReflectConstruct,
            args,
            ..
        } if args.len() == 3 => true,
        LoweredExpr::RuntimeCall {
            intrinsic:
                RuntimeFn::BigIntMixedArithmeticTypeError
                | RuntimeFn::BigIntDivisionByZeroRangeError
                | RuntimeFn::BigIntDiv
                | RuntimeFn::BigIntRem,
            ..
        } => true,
        LoweredExpr::RuntimeCall {
            intrinsic, args, ..
        } if native_runtime_function_available(*intrinsic) => args
            .iter()
            .any(|arg| native_expr_may_throw(arg, ctx, functions, function_results)),
        LoweredExpr::RuntimeCall { .. }
        | LoweredExpr::New { .. }
        | LoweredExpr::MethodCall { .. }
        | LoweredExpr::OptionalCall { .. }
        | LoweredExpr::PropertyIn { .. }
        | LoweredExpr::PropertyInDynamic { .. }
        | LoweredExpr::LogicalPropertyAssign { .. }
        | LoweredExpr::LogicalComputedPropertyAssign { .. }
        | LoweredExpr::LogicalComputedMemberAssign { .. }
        | LoweredExpr::LogicalMemberAssign { .. } => true,
        LoweredExpr::PropertyGet { obj, key, .. }
        | LoweredExpr::OptionalPropertyGet { obj, key, .. } => {
            native_expr_may_throw(obj, ctx, functions, function_results)
                || !(static_object_slot(ctx, obj, key).is_some()
                    || static_object_property(ctx, obj, key).is_some()
                    || static_object_known(ctx, obj))
        }
        LoweredExpr::PropertyGetDynamic { obj, key, .. }
        | LoweredExpr::OptionalIndex {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::Index {
            object: obj,
            index: key,
            ..
        }
        | LoweredExpr::ArrayGet {
            arr: obj,
            index: key,
            ..
        } => {
            native_expr_may_throw(obj, ctx, functions, function_results)
                || native_expr_may_throw(key, ctx, functions, function_results)
                || !(static_array_slot(ctx, obj, key).is_some()
                    || static_object_dynamic_slot(ctx, obj, key).is_some()
                    || static_array_element(ctx, obj, key).is_some()
                    || static_object_dynamic_property(ctx, obj, key).is_some()
                    || static_object_known(ctx, obj))
        }
        LoweredExpr::PropertySet { object, value, .. } => {
            native_expr_may_throw(object, ctx, functions, function_results)
                || native_expr_may_throw(value, ctx, functions, function_results)
        }
        LoweredExpr::PropertyDelete { object, .. } => {
            native_expr_may_throw(object, ctx, functions, function_results)
        }
        LoweredExpr::PropertyDeleteDynamic { object, key, .. } => {
            native_expr_may_throw(object, ctx, functions, function_results)
                || native_expr_may_throw(key, ctx, functions, function_results)
        }
        LoweredExpr::PropertySetDynamic {
            object,
            index,
            value,
            ..
        } => {
            native_expr_may_throw(object, ctx, functions, function_results)
                || native_expr_may_throw(index, ctx, functions, function_results)
                || native_expr_may_throw(value, ctx, functions, function_results)
        }
        LoweredExpr::GetLength(inner, _) => {
            native_expr_may_throw(inner, ctx, functions, function_results)
                || static_array_len(ctx, inner).is_none()
        }
    }
}

fn function_returns_value(function: &LoweredFunction) -> bool {
    static_new_uses_function_constructor_semantics(function) || stmts_return_value(&function.body)
}

fn stmts_return_value(stmts: &[LoweredStmt]) -> bool {
    stmts.iter().any(stmt_returns_value)
}

fn stmt_returns_value(stmt: &LoweredStmt) -> bool {
    match stmt {
        LoweredStmt::Return(_, _) => true,
        LoweredStmt::Block(stmts, _) => stmts_return_value(stmts),
        LoweredStmt::If {
            then_body,
            else_body,
            ..
        } => stmts_return_value(then_body) || stmts_return_value(else_body),
        LoweredStmt::While { body, .. } => stmts_return_value(body),
        _ => false,
    }
}

fn expr_produces_value(expr: &LoweredExpr, function_results: &HashMap<FuncId, bool>) -> bool {
    match expr {
        LoweredExpr::Call {
            kind: FunctionCallKind::User(id),
            ..
        } => function_results.get(id).copied().unwrap_or(false),
        LoweredExpr::Call {
            kind: FunctionCallKind::Builtin(BuiltinId::ConsoleLog),
            ..
        } => false,
        LoweredExpr::Call {
            kind: FunctionCallKind::Builtin(BuiltinId::ProcessExit),
            ..
        } => false,
        LoweredExpr::RuntimeCall { intrinsic, .. } => intrinsic.is_value(),
        _ => true,
    }
}

fn body_ends_with_return(body: &[WasmInstr]) -> bool {
    matches!(body.last(), Some(WasmInstr::Return))
}

fn unsupported(message: &str) -> Diagnostic {
    Diagnostic {
        code: ts2wasm_diagnostic::resolve_diag_code(message),
        message: message.to_owned(),
        span: None,
        phase: None,
    }
}

#[cfg(test)]
mod native_lowered_static_host_tests {
    use super::*;

    #[test]
    fn static_host_function_body_preserves_global_object_growth() {
        let span = Span::generated("static-host-test");
        let body = concat!(
            "globalThis.__ts2wasmObjectGrowth = globalThis.__ts2wasmObjectGrowth || ",
            "{ a: 1, b: 2, c: 3, d: 4 };",
            "if (globalThis.__ts2wasmObjectGrowthSeen) { ",
            "globalThis.__ts2wasmObjectGrowth.e = 5; }",
            "globalThis.__ts2wasmObjectGrowthSeen = true;",
            "return globalThis.__ts2wasmObjectGrowth",
        );
        let mut locals = HashMap::new();
        assert!(
            static_split_host_function_statements(body)
                .iter()
                .any(|stmt| stmt.contains("__ts2wasmObjectGrowth.e = 5"))
        );
        let split = static_split_host_function_statements(body);
        let if_stmt = split
            .iter()
            .find(|stmt| stmt.starts_with("if "))
            .unwrap_or_else(|| panic!("{split:?}"));
        assert_eq!(
            if_stmt,
            "if (globalThis.__ts2wasmObjectGrowthSeen) { globalThis.__ts2wasmObjectGrowth.e = 5; }"
        );
        let (_, if_body) = static_host_if_parts(&if_stmt).unwrap();
        assert_eq!(if_body, "globalThis.__ts2wasmObjectGrowth.e = 5;");

        static_execute_host_function_body(body, span, &mut locals).unwrap();
        assert_eq!(
            static_global_property_value(&locals, "__ts2wasmObjectGrowthSeen")
                .and_then(|value| static_truthy_value(&value)),
            Some(true)
        );
        assert!(
            static_object_value_from_root(
                &locals,
                static_global_property_root("__ts2wasmObjectGrowth"),
            )
            .unwrap()
            .get("e")
            .is_none()
        );

        static_execute_host_function_body(body, span, &mut locals).unwrap();
        assert_eq!(
            static_eval_host_condition(
                "globalThis.__ts2wasmObjectGrowthSeen",
                &locals,
                &HashMap::new(),
            ),
            Some(true)
        );
        assert!(
            static_object_value_from_root(
                &locals,
                static_global_property_root("__ts2wasmObjectGrowth"),
            )
            .unwrap()
            .get("e")
            .is_some()
        );
    }

    #[test]
    fn static_regexp_helpers_reject_non_ascii_input_without_panicking() {
        let span = Span::generated("static-regexp-test");
        let args = [
            LoweredExpr::String("🐸BC".to_owned(), span),
            LoweredExpr::String(".".to_owned(), span),
            LoweredExpr::String("x".to_owned(), span),
        ];

        assert!(
            static_regexp_runtime_value(
                RuntimeFn::StringReplaceAll,
                &args[..2],
                span,
                &HashMap::new(),
                &[],
            )
            .is_none()
        );

        assert!(
            static_string_regexp_replace_value(
                RuntimeFn::StringReplaceAll,
                &args,
                span,
                &HashMap::new(),
                &[],
            )
            .is_none()
        );
    }

    #[test]
    fn static_eval_host_value_preserves_regexp_source_escapes() {
        let span = Span::generated("static-regexp-eval-test");
        let locals = HashMap::new();
        let functions = [];
        let source = LoweredExpr::String(r#"/\u2028/.source"#.to_owned(), span);
        let value = static_eval_host_value(&[source], span, &locals, &functions)
            .expect("static eval should succeed");
        match value {
            StaticValue::Primitive(LoweredExpr::String(text, _)) => {
                assert_eq!(text, r#"\u2028"#);
            }
            _ => panic!("expected a primitive string result"),
        }
    }
}
